import { useCallback, useEffect, useRef, useState } from 'react';
import confetti from 'canvas-confetti';
import './index.css';
import Menu from './components/Menu';
import Hud, { Toast } from './components/Hud';
import { GameOver, PauseMenu } from './components/Overlays';
import { Game, HudState, RunResult } from './game/engine';
import { CarDef, carById, diffById, loadSave, storeSave, SaveData } from './game/config';
import { sound } from './game/audio';

type Screen = 'menu' | 'play' | 'pause' | 'over';

const EMPTY_HUD: HudState = {
  score: 0, distance: 0, kmh: 0, speedN: 0, nitro: 0, nitroOn: false, lives: 3, maxLives: 3,
  combo: 0, comboT: 0, coins: 0, sector: 1, shield: 0, magnet: 0,
};

export default function App() {
  const hostRef = useRef<HTMLDivElement>(null);
  const gameRef = useRef<Game | null>(null);
  const [screen, setScreen] = useState<Screen>('menu');
  const screenRef = useRef<Screen>('menu');
  const [hud, setHud] = useState<HudState>(EMPTY_HUD);
  const [save, setSave] = useState<SaveData>(() => loadSave());
  const saveRef = useRef(save);
  const [result, setResult] = useState<{ r: RunResult; record: boolean } | null>(null);
  const [toasts, setToasts] = useState<Toast[]>([]);
  const [muted, setMuted] = useState(false);
  const [hitFlash, setHitFlash] = useState(0);
  const [touch] = useState(() => typeof window !== 'undefined' && (window.matchMedia?.('(pointer: coarse)').matches ?? false));
  const timers = useRef<number[]>([]);
  const toastId = useRef(0);

  const go = (s: Screen) => { screenRef.current = s; setScreen(s); };
  const persist = (s: SaveData) => { saveRef.current = s; setSave(s); storeSave(s); };

  // Crear el motor una sola vez
  useEffect(() => {
    const host = hostRef.current;
    if (!host) return;
    const game = new Game(host, {
      onHud: h => setHud(h),
      onEvent: (text, color) => {
        const id = ++toastId.current;
        if (text.startsWith('¡CHOQUE')) setHitFlash(id);
        setToasts(t => [...t.slice(-2), { id, text, color }]);
        timers.current.push(window.setTimeout(() => setToasts(t => t.filter(x => x.id !== id)), 1300));
      },
      onGameOver: r => {
        const prev = saveRef.current;
        const record = r.score > prev.best;
        persist({ ...prev, best: Math.max(prev.best, r.score), bestDist: Math.max(prev.bestDist, r.distance), coins: prev.coins + r.coins });
        setResult({ r, record });
        go('over');
        if (record) {
          try { confetti({ particleCount: 140, spread: 90, origin: { y: 0.35 }, colors: ['#ff3bd9', '#22e6ff', '#ffc23d'] }); } catch { /* sin confeti */ }
        }
      },
    });
    game.setCar(carById(saveRef.current.car));
    gameRef.current = game;
    return () => {
      timers.current.forEach(t => window.clearTimeout(t));
      timers.current = [];
      game.dispose();
      gameRef.current = null;
    };
  }, []);

  const start = useCallback(() => {
    const g = gameRef.current; if (!g) return;
    const s = saveRef.current;
    if (!s.unlocked.includes(s.car)) return;
    sound.init();
    (document.activeElement as HTMLElement | null)?.blur?.();
    setToasts([]); setResult(null); setHud(EMPTY_HUD);
    g.newRun(carById(s.car), diffById(s.diff));
    go('play');
  }, []);

  const toMenu = useCallback(() => {
    gameRef.current?.toAttract();
    setToasts([]);
    go('menu');
  }, []);

  const setPaused = useCallback((p: boolean) => {
    const g = gameRef.current; if (!g) return;
    g.setPaused(p);
    go(p ? 'pause' : 'play');
  }, []);

  // Pausa con Esc / P
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.code !== 'Escape' && e.code !== 'KeyP') return;
      const s = screenRef.current;
      if (s === 'play') setPaused(true);
      else if (s === 'pause') setPaused(false);
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [setPaused]);

  const toggleMute = () => { sound.init(); sound.setMuted(!muted); setMuted(!muted); };

  const selectCar = (id: string) => {
    sound.click();
    persist({ ...saveRef.current, car: id });
    gameRef.current?.setCar(carById(id));
  };

  const unlock = (c: CarDef) => {
    const s = saveRef.current;
    if (s.coins < c.price || s.unlocked.includes(c.id)) return;
    sound.init(); sound.powerUp();
    persist({ ...s, coins: s.coins - c.price, unlocked: [...s.unlocked, c.id], car: c.id });
    try { confetti({ particleCount: 80, spread: 70, origin: { x: 0.8, y: 0.5 } }); } catch { /* sin confeti */ }
  };

  return (
    <div className="nh-root relative h-screen min-h-[420px] w-full overflow-hidden bg-[#07020f]">
      <div ref={hostRef} className="absolute inset-0" />
      <div className="nh-vignette absolute inset-0" />
      <div className="nh-scan absolute inset-0 opacity-40" />

      {screen === 'menu' && (
        <Menu
          save={save} carId={save.car} diffId={save.diff} muted={muted}
          onSelectCar={selectCar} onUnlock={unlock}
          onSelectDiff={id => { sound.click(); persist({ ...saveRef.current, diff: id }); }}
          onToggleMute={toggleMute} onPlay={start}
        />
      )}

      {(screen === 'play' || screen === 'pause') && gameRef.current && (
        <Hud hud={hud} toasts={toasts} muted={muted} touch={touch} hitFlash={hitFlash}
          onPause={() => setPaused(true)} onToggleMute={toggleMute} pad={gameRef.current.input.virtual} />
      )}

      {screen === 'pause' && (
        <PauseMenu onResume={() => setPaused(false)} onRestart={start} onMenu={toMenu} />
      )}

      {screen === 'over' && result && (
        <GameOver r={result.r} best={save.best} isRecord={result.record} onRetry={start} onMenu={toMenu} />
      )}
    </div>
  );
}

import { ChevronLeft, ChevronRight, ChevronsDown, Coins, Heart, Magnet, Pause, Shield, Volume2, VolumeX, Zap } from 'lucide-react';
import clsx from 'clsx';
import type { HudState } from '../game/engine';
import type { VirtualPad } from '../game/input';
import type { ReactNode } from 'react';

export interface Toast { id: number; text: string; color: string }

interface Props {
  hud: HudState;
  toasts: Toast[];
  muted: boolean;
  touch: boolean;
  hitFlash: number;
  onPause(): void;
  onToggleMute(): void;
  pad: VirtualPad;
}

function Speedo({ kmh, n, nitroOn }: { kmh: number; n: number; nitroOn: boolean }) {
  const R = 52; const C = Math.PI * 2 * R; const arc = 0.75;
  const v = Math.min(1, n);
  return (
    <div className="relative h-36 w-36">
      <svg viewBox="0 0 128 128" className="h-full w-full -rotate-[225deg]">
        <circle cx="64" cy="64" r={R} fill="rgba(10,2,26,0.7)" stroke="rgba(255,255,255,0.08)" strokeWidth="9"
          strokeDasharray={`${C * arc} ${C}`} />
        <circle cx="64" cy="64" r={R} fill="none" stroke={nitroOn ? '#22e6ff' : 'url(#nhg)'} strokeWidth="9" strokeLinecap="round"
          strokeDasharray={`${C * arc * v} ${C}`} style={{ filter: `drop-shadow(0 0 6px ${nitroOn ? '#22e6ff' : '#ff3bd9'})` }} />
        <defs>
          <linearGradient id="nhg" x1="0" y1="0" x2="1" y2="1">
            <stop offset="0%" stopColor="#7a3bff" /><stop offset="60%" stopColor="#ff3bd9" /><stop offset="100%" stopColor="#ffc23d" />
          </linearGradient>
        </defs>
      </svg>
      <div className="absolute inset-0 flex flex-col items-center justify-center">
        <div className={clsx('font-mono text-4xl font-black italic', nitroOn ? 'text-cyan-200' : 'text-white')}
          style={{ textShadow: '0 0 12px rgba(255,59,217,0.8)' }}>{kmh}</div>
        <div className="text-[10px] font-bold tracking-[0.3em] text-violet-300">KM/H</div>
      </div>
    </div>
  );
}

function TouchButton({ onSet, children, className }: { onSet(v: boolean): void; children: ReactNode; className?: string }) {
  return (
    <button
      className={clsx('nh-glass pointer-events-auto flex select-none items-center justify-center rounded-full text-white active:scale-95', className)}
      onPointerDown={e => { e.preventDefault(); (e.target as HTMLElement).setPointerCapture?.(e.pointerId); onSet(true); }}
      onPointerUp={() => onSet(false)}
      onPointerCancel={() => onSet(false)}
      onPointerLeave={() => onSet(false)}
      onContextMenu={e => e.preventDefault()}
    >
      {children}
    </button>
  );
}

export default function Hud({ hud, toasts, muted, touch, hitFlash, onPause, onToggleMute, pad }: Props) {
  const hearts = Array.from({ length: hud.maxLives }, (_, i) => i < hud.lives);
  return (
    <div className="pointer-events-none absolute inset-0 z-10 text-white">
      {hitFlash > 0 && <div key={hitFlash} className="nh-hit absolute inset-0 bg-rose-500/40" />}

      {/* Arriba izquierda: puntos y combo */}
      <div className="absolute left-3 top-3 md:left-5 md:top-5">
        <div className="text-[10px] font-bold uppercase tracking-[0.4em] text-fuchsia-300">Puntos</div>
        <div className="nh-chrome font-mono text-4xl md:text-5xl">{hud.score.toLocaleString('es-ES')}</div>
        {hud.combo > 0 && (
          <div className="mt-1 w-40">
            <div className="text-lg font-black italic text-amber-300" style={{ textShadow: '0 0 10px #ff7a3b' }}>COMBO x{hud.combo}</div>
            <div className="h-1 overflow-hidden rounded-full bg-white/10">
              <div className="h-full bg-gradient-to-r from-fuchsia-400 to-amber-300" style={{ width: `${Math.max(0, hud.comboT) * 100}%` }} />
            </div>
          </div>
        )}
      </div>

      {/* Arriba centro: vidas y power-ups */}
      <div className="absolute left-1/2 top-3 flex -translate-x-1/2 flex-col items-center gap-1 md:top-5">
        <div className="flex gap-1.5">
          {hearts.map((on, i) => (
            <Heart key={i} className={clsx('h-6 w-6', on ? 'fill-rose-500 text-rose-300' : 'text-white/25')}
              style={on ? { filter: 'drop-shadow(0 0 6px #ff3b6b)' } : undefined} />
          ))}
        </div>
        <div className="flex gap-2 text-xs font-bold">
          {hud.shield > 0 && <span className="nh-glass flex items-center gap-1 rounded-full px-2 py-0.5 text-emerald-300"><Shield className="h-3.5 w-3.5" />{Math.ceil(hud.shield)}s</span>}
          {hud.magnet > 0 && <span className="nh-glass flex items-center gap-1 rounded-full px-2 py-0.5 text-fuchsia-300"><Magnet className="h-3.5 w-3.5" />{Math.ceil(hud.magnet)}s</span>}
        </div>
      </div>

      {/* Arriba derecha: datos y botones */}
      <div className="absolute right-3 top-3 flex items-start gap-2 md:right-5 md:top-5">
        <div className="nh-glass rounded-xl px-3 py-2 text-right">
          <div className="flex items-center justify-end gap-1 font-mono text-lg font-bold text-yellow-200"><Coins className="h-4 w-4" />{hud.coins}</div>
          <div className="text-[10px] uppercase tracking-widest text-violet-300">Sector {hud.sector} · {(hud.distance / 1000).toFixed(2)} km</div>
        </div>
        <button onClick={onToggleMute} aria-label="Sonido" className="nh-glass pointer-events-auto rounded-xl p-2.5 text-cyan-200">
          {muted ? <VolumeX className="h-5 w-5" /> : <Volume2 className="h-5 w-5" />}
        </button>
        <button onClick={onPause} aria-label="Pausa" className="nh-glass pointer-events-auto rounded-xl p-2.5 text-cyan-200">
          <Pause className="h-5 w-5" />
        </button>
      </div>

      {/* Abajo derecha: velocímetro y nitro */}
      <div className={clsx('absolute flex flex-col items-center', touch ? 'bottom-36 right-3' : 'bottom-4 right-5')}>
        <Speedo kmh={hud.kmh} n={hud.speedN} nitroOn={hud.nitroOn} />
        <div className="mt-1 w-36">
          <div className="mb-0.5 flex items-center gap-1 text-[10px] font-bold tracking-[0.3em] text-cyan-300"><Zap className="h-3 w-3" />NITRO</div>
          <div className="h-2.5 overflow-hidden rounded-full border border-cyan-300/40 bg-black/40">
            <div className={clsx('h-full bg-gradient-to-r from-sky-500 to-cyan-200', hud.nitroOn && 'nh-pulse')}
              style={{ width: `${hud.nitro * 100}%`, boxShadow: '0 0 10px #22e6ff' }} />
          </div>
        </div>
      </div>

      {/* Avisos */}
      {toasts.map(t => (
        <div key={t.id} className="nh-toast absolute left-1/2 top-[30%] whitespace-nowrap text-3xl font-black italic md:text-4xl"
          style={{ color: t.color, textShadow: `0 0 18px ${t.color}, 0 3px 0 #1a0228` }}>{t.text}</div>
      ))}

      {/* Controles táctiles */}
      {touch && (
        <div className="absolute inset-x-0 bottom-0 flex items-end justify-between p-4">
          <div className="flex gap-3">
            <TouchButton className="h-20 w-20" onSet={v => { pad.left = v; }}><ChevronLeft className="h-10 w-10" /></TouchButton>
            <TouchButton className="h-20 w-20" onSet={v => { pad.right = v; }}><ChevronRight className="h-10 w-10" /></TouchButton>
          </div>
          <div className="flex items-end gap-3">
            <TouchButton className="h-16 w-16 text-rose-200" onSet={v => { pad.down = v; }}><ChevronsDown className="h-8 w-8" /></TouchButton>
            <TouchButton className="h-24 w-24 border-cyan-300 text-cyan-200" onSet={v => { pad.nitro = v; pad.up = v; }}>
              <div className="flex flex-col items-center"><Zap className="h-9 w-9" /><span className="text-[10px] font-bold">NITRO</span></div>
            </TouchButton>
          </div>
        </div>
      )}
    </div>
  );
}

import { Coins, Gauge, Lock, Trophy, Volume2, VolumeX, Wind, Zap } from 'lucide-react';
import clsx from 'clsx';
import type { ReactNode } from 'react';
import { CARS, DIFFS, CarDef, SaveData } from '../game/config';

interface Props {
  save: SaveData;
  carId: string;
  diffId: string;
  muted: boolean;
  onSelectCar(id: string): void;
  onUnlock(car: CarDef): void;
  onSelectDiff(id: string): void;
  onToggleMute(): void;
  onPlay(): void;
}

function Stat({ label, value, color, icon }: { label: string; value: number; color: string; icon: ReactNode }) {
  return (
    <div className="flex items-center gap-2 text-[11px] uppercase tracking-wider text-violet-200/80">
      <span className="w-4 opacity-80">{icon}</span>
      <span className="w-16">{label}</span>
      <div className="h-1.5 flex-1 overflow-hidden rounded-full bg-white/10">
        <div className="h-full rounded-full" style={{ width: `${Math.round(value * 100)}%`, background: color, boxShadow: `0 0 8px ${color}` }} />
      </div>
    </div>
  );
}

export default function Menu(p: Props) {
  const sel = CARS.find(c => c.id === p.carId) ?? CARS[0];
  const unlocked = p.save.unlocked.includes(sel.id);
  return (
    <div className="absolute inset-0 z-20 flex flex-col justify-between overflow-y-auto p-4 md:flex-row md:items-stretch md:p-8">
      <div className="pointer-events-none absolute inset-0 bg-gradient-to-r from-[#0b0220]/90 via-transparent to-[#0b0220]/90" />

      {/* Columna izquierda: título y explicación */}
      <div className="relative flex max-w-md flex-col gap-4">
        <div>
          <div className="nh-chrome text-xs tracking-[0.5em] text-cyan-200">NONA ARCADE · 1986</div>
          <h1 className="nh-title text-6xl leading-[0.9] md:text-7xl">NEON<br />HIGHWAY</h1>
        </div>
        <p className="text-sm leading-relaxed text-violet-100/90">
          Medianoche en la autopista infinita. Esquiva el tráfico en cuatro carriles, roza los coches
          <span className="font-bold text-fuchsia-300"> al límite </span>para encadenar combos, recoge monedas y quema el
          <span className="font-bold text-cyan-300"> nitro</span> bajo el sol retro.
        </p>
        <div className="nh-glass hidden rounded-xl p-3 text-xs text-violet-100/90 sm:block">
          <div className="mb-1 font-bold uppercase tracking-widest text-fuchsia-300">Controles</div>
          <div className="grid grid-cols-2 gap-x-4 gap-y-1">
            <span>← → / A D</span><span>Cambiar de carril</span>
            <span>↑ / W</span><span>Acelerar</span>
            <span>↓ / S</span><span>Frenar</span>
            <span>Espacio</span><span>Nitro</span>
            <span>Esc / P</span><span>Pausa</span>
          </div>
        </div>
        <div className="flex gap-3">
          <div className="nh-glass flex items-center gap-2 rounded-xl px-3 py-2">
            <Trophy className="h-5 w-5 text-amber-300" />
            <div>
              <div className="text-[10px] uppercase tracking-widest text-violet-300">Récord</div>
              <div className="font-mono text-lg font-bold text-amber-200">{p.save.best.toLocaleString('es-ES')}</div>
            </div>
          </div>
          <div className="nh-glass flex items-center gap-2 rounded-xl px-3 py-2">
            <Coins className="h-5 w-5 text-yellow-300" />
            <div>
              <div className="text-[10px] uppercase tracking-widest text-violet-300">Monedas</div>
              <div className="font-mono text-lg font-bold text-yellow-200">{p.save.coins}</div>
            </div>
          </div>
          <button
            onClick={p.onToggleMute}
            aria-label={p.muted ? 'Activar sonido' : 'Silenciar'}
            className="nh-glass flex w-12 items-center justify-center rounded-xl text-cyan-200 hover:text-white"
          >
            {p.muted ? <VolumeX className="h-5 w-5" /> : <Volume2 className="h-5 w-5" />}
          </button>
        </div>
      </div>

      {/* Columna derecha: garaje, dificultad y botón */}
      <div className="relative mt-4 flex w-full max-w-sm flex-col gap-3 md:mt-0 md:justify-end">
        <div className="nh-glass rounded-2xl p-3">
          <div className="mb-2 text-xs font-bold uppercase tracking-[0.3em] text-cyan-300">Garaje</div>
          <div className="grid grid-cols-3 gap-2">
            {CARS.map(c => {
              const own = p.save.unlocked.includes(c.id);
              return (
                <button
                  key={c.id}
                  onClick={() => p.onSelectCar(c.id)}
                  className={clsx('relative rounded-lg border px-2 py-2 text-left transition',
                    p.carId === c.id ? 'border-white/70 bg-white/10' : 'border-white/10 hover:border-white/30')}
                  style={p.carId === c.id ? { boxShadow: `0 0 16px ${c.css}88` } : undefined}
                >
                  <div className="mb-1 h-1 rounded-full" style={{ background: c.css, boxShadow: `0 0 8px ${c.css}` }} />
                  <div className="text-xs font-bold italic text-white">{c.name}</div>
                  <div className="flex items-center gap-1 text-[10px] text-violet-300">
                    {own ? 'Disponible' : (<><Lock className="h-3 w-3" /> {c.price}</>)}
                  </div>
                </button>
              );
            })}
          </div>
          <div className="mt-3 space-y-1.5">
            <div className="text-[11px] italic text-violet-200">{sel.tagline}</div>
            <Stat label="Velocidad" value={sel.maxSpeed / 70} color={sel.css} icon={<Gauge className="h-3.5 w-3.5" />} />
            <Stat label="Aceler." value={sel.accel / 24} color={sel.css} icon={<Zap className="h-3.5 w-3.5" />} />
            <Stat label="Manejo" value={sel.handling / 19} color={sel.css} icon={<Wind className="h-3.5 w-3.5" />} />
            <Stat label="Nitro" value={sel.nitroCap / 1.4} color={sel.css} icon={<Zap className="h-3.5 w-3.5" />} />
          </div>
          {!unlocked && (
            <button
              onClick={() => p.onUnlock(sel)}
              disabled={p.save.coins < sel.price}
              className="mt-3 w-full rounded-lg border border-yellow-300/60 py-2 text-sm font-bold text-yellow-200 enabled:hover:bg-yellow-300/10 disabled:opacity-40"
            >
              Desbloquear por {sel.price} monedas
            </button>
          )}
        </div>

        <div className="nh-glass rounded-2xl p-3">
          <div className="mb-2 text-xs font-bold uppercase tracking-[0.3em] text-fuchsia-300">Dificultad</div>
          <div className="grid grid-cols-3 gap-2">
            {DIFFS.map(d => (
              <button
                key={d.id}
                onClick={() => p.onSelectDiff(d.id)}
                className={clsx('rounded-lg border py-1.5 text-sm font-bold italic transition',
                  p.diffId === d.id ? 'border-fuchsia-300 bg-fuchsia-500/20 text-white' : 'border-white/10 text-violet-200 hover:border-white/30')}
              >
                {d.name}
                <div className="text-[10px] font-normal not-italic text-violet-300">{d.lives} vidas · x{d.scoreMul}</div>
              </button>
            ))}
          </div>
        </div>

        <button
          onClick={p.onPlay}
          disabled={!unlocked}
          className="nh-btn rounded-2xl py-4 text-2xl disabled:opacity-50"
        >
          {unlocked ? 'Jugar' : 'Coche bloqueado'}
        </button>
      </div>
    </div>
  );
}

import { Coins, Flag, Home, Play as PlayIcon, RotateCcw, Sparkles, Trophy, Zap } from 'lucide-react';
import type { ReactNode } from 'react';
import type { RunResult } from '../game/engine';

function Panel({ children }: { children: ReactNode }) {
  return (
    <div className="absolute inset-0 z-30 flex items-center justify-center bg-[#07010f]/70 p-4 backdrop-blur-sm">
      <div className="nh-glass w-full max-w-md rounded-3xl p-6 text-center text-white">{children}</div>
    </div>
  );
}

function Btn({ onClick, icon, children, primary }: { onClick(): void; icon: ReactNode; children: ReactNode; primary?: boolean }) {
  return (
    <button
      onClick={onClick}
      className={primary
        ? 'nh-btn flex w-full items-center justify-center gap-2 rounded-xl py-3 text-lg'
        : 'flex w-full items-center justify-center gap-2 rounded-xl border border-white/20 py-2.5 font-bold italic text-violet-100 hover:border-fuchsia-300 hover:bg-white/5'}
    >
      {icon}{children}
    </button>
  );
}

export function PauseMenu({ onResume, onRestart, onMenu }: { onResume(): void; onRestart(): void; onMenu(): void }) {
  return (
    <Panel>
      <div className="nh-title mb-1 text-5xl">PAUSA</div>
      <div className="mb-6 text-sm text-violet-200">El motor sigue caliente. ¿Seguimos?</div>
      <div className="flex flex-col gap-3">
        <Btn primary onClick={onResume} icon={<PlayIcon className="h-5 w-5" />}>Continuar</Btn>
        <Btn onClick={onRestart} icon={<RotateCcw className="h-5 w-5" />}>Reiniciar</Btn>
        <Btn onClick={onMenu} icon={<Home className="h-5 w-5" />}>Menú principal</Btn>
      </div>
