// Audio procedural con Web Audio API: motor, efectos y una música synthwave sencilla.

type Ctx = AudioContext;

class Sound {
  private ctx: Ctx | null = null;
  private master: GainNode | null = null;
  private sfxBus: GainNode | null = null;
  private musicBus: GainNode | null = null;
  private engOsc: OscillatorNode | null = null;
  private engOsc2: OscillatorNode | null = null;
  private engGain: GainNode | null = null;
  private engFilter: BiquadFilterNode | null = null;
  private noiseBuf: AudioBuffer | null = null;
  private musicTimer: number | null = null;
  private nextNote = 0;
  private step = 0;
  muted = false;

  /** Llamar desde un gesto del usuario. */
  init() {
    if (this.ctx) { if (this.ctx.state === 'suspended') this.ctx.resume().catch(() => {}); return; }
    const AC = window.AudioContext || (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
    if (!AC) return;
    const ctx = new AC();
    this.ctx = ctx;
    this.master = ctx.createGain();
    this.master.gain.value = this.muted ? 0 : 0.7;
    this.master.connect(ctx.destination);
    this.sfxBus = ctx.createGain(); this.sfxBus.gain.value = 0.8; this.sfxBus.connect(this.master);
    this.musicBus = ctx.createGain(); this.musicBus.gain.value = 0.32; this.musicBus.connect(this.master);
    const len = ctx.sampleRate;
    this.noiseBuf = ctx.createBuffer(1, len, ctx.sampleRate);
    const d = this.noiseBuf.getChannelData(0);
    for (let i = 0; i < len; i++) d[i] = Math.random() * 2 - 1;
  }

  setMuted(m: boolean) {
    this.muted = m;
    if (this.master && this.ctx) this.master.gain.setTargetAtTime(m ? 0 : 0.7, this.ctx.currentTime, 0.05);
  }

  private tone(freq: number, dur: number, type: OscillatorType, vol: number, slideTo?: number, delay = 0) {
    const ctx = this.ctx; if (!ctx || !this.sfxBus) return;
    const t = ctx.currentTime + delay;
    const o = ctx.createOscillator(); const g = ctx.createGain();
    o.type = type; o.frequency.setValueAtTime(freq, t);
    if (slideTo) o.frequency.exponentialRampToValueAtTime(slideTo, t + dur);
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(vol, t + 0.01);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    o.connect(g); g.connect(this.sfxBus);
    o.start(t); o.stop(t + dur + 0.05);
  }

  private noise(dur: number, vol: number, f0: number, f1: number, type: BiquadFilterType = 'lowpass', bus?: GainNode, when?: number) {
    const ctx = this.ctx; if (!ctx || !this.noiseBuf) return;
    const out = bus ?? this.sfxBus; if (!out) return;
    const t = when ?? ctx.currentTime;
    const s = ctx.createBufferSource(); s.buffer = this.noiseBuf;
    const f = ctx.createBiquadFilter(); f.type = type;
    f.frequency.setValueAtTime(f0, t); f.frequency.exponentialRampToValueAtTime(Math.max(40, f1), t + dur);
    const g = ctx.createGain();
    g.gain.setValueAtTime(vol, t); g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    s.connect(f); f.connect(g); g.connect(out);
    s.start(t, Math.random() * 0.5); s.stop(t + dur + 0.05);
  }

  startEngine() {
    const ctx = this.ctx; if (!ctx || !this.sfxBus || this.engOsc) return;
    this.engOsc = ctx.createOscillator(); this.engOsc.type = 'sawtooth';
    this.engOsc2 = ctx.createOscillator(); this.engOsc2.type = 'square';
    this.engFilter = ctx.createBiquadFilter(); this.engFilter.type = 'lowpass'; this.engFilter.frequency.value = 500;
    this.engGain = ctx.createGain(); this.engGain.gain.value = 0;
    this.engOsc.connect(this.engFilter); this.engOsc2.connect(this.engFilter);
    this.engFilter.connect(this.engGain); this.engGain.connect(this.sfxBus);
    this.engOsc.start(); this.engOsc2.start();
  }

  stopEngine() {
    try { this.engOsc?.stop(); this.engOsc2?.stop(); } catch { /* ya parado */ }
    this.engGain?.disconnect();
    this.engOsc = this.engOsc2 = null; this.engGain = null; this.engFilter = null;
  }

  /** speedN 0..1(+), nitro activo */
  engine(speedN: number, nitro: boolean) {
    const ctx = this.ctx; if (!ctx || !this.engOsc || !this.engOsc2 || !this.engGain || !this.engFilter) return;
    const t = ctx.currentTime;
    const f = 48 + speedN * 95 + (nitro ? 40 : 0);
    this.engOsc.frequency.setTargetAtTime(f, t, 0.08);
    this.engOsc2.frequency.setTargetAtTime(f * 0.5 + 1.5, t, 0.08);
    this.engFilter.frequency.setTargetAtTime(380 + speedN * 900 + (nitro ? 900 : 0), t, 0.1);
    this.engGain.gain.setTargetAtTime(0.05 + speedN * 0.05, t, 0.1);
  }

  coin() { this.tone(988, 0.08, 'square', 0.12); this.tone(1480, 0.16, 'square', 0.1, undefined, 0.06); }
  nearMiss(combo: number) {
    const base = 520 + Math.min(combo, 10) * 70;
    this.tone(base, 0.18, 'sawtooth', 0.12, base * 2);
    this.noise(0.25, 0.18, 6000, 800, 'bandpass');
  }
  nitro() { this.noise(0.9, 0.35, 400, 4000, 'bandpass'); this.tone(110, 0.7, 'sawtooth', 0.15, 440); }
  powerUp() { [660, 880, 1320].forEach((f, i) => this.tone(f, 0.14, 'triangle', 0.16, undefined, i * 0.07)); }
  crash() { this.noise(0.7, 0.9, 2500, 80); this.tone(140, 0.5, 'sawtooth', 0.3, 35); }
  shieldHit() { this.tone(1200, 0.3, 'triangle', 0.2, 300); this.noise(0.3, 0.3, 3000, 500, 'highpass'); }
  scrape() { this.noise(0.12, 0.12, 5000, 2000, 'highpass'); }
  sector() { [523, 659, 784, 1046].forEach((f, i) => this.tone(f, 0.22, 'square', 0.1, undefined, i * 0.09)); }
  gameOver() { [392, 330, 262, 196].forEach((f, i) => this.tone(f, 0.35, 'sawtooth', 0.14, undefined, i * 0.18)); }
  click() { this.tone(700, 0.05, 'square', 0.08); }

  startMusic() {
    const ctx = this.ctx; if (!ctx || this.musicTimer !== null) return;
    this.nextNote = ctx.currentTime + 0.1; this.step = 0;
    this.musicTimer = window.setInterval(() => this.schedule(), 50);
  }

  stopMusic() {
    if (this.musicTimer !== null) window.clearInterval(this.musicTimer);
    this.musicTimer = null;
  }

  private schedule() {
    const ctx = this.ctx; if (!ctx || !this.musicBus) return;
    const stepDur = 60 / 112 / 4; // semicorcheas a 112 bpm
    const roots = [45, 45, 41, 43]; // La, La, Fa, Sol (MIDI)
    while (this.nextNote < ctx.currentTime + 0.2) {
      const t = this.nextNote; const s = this.step;
      const bar = Math.floor(s / 16) % 4;
      const root = roots[bar];
      // bajo en corcheas con octava
      if (s % 2 === 0) {
        const n = root + ((s / 2) % 2 === 1 ? 12 : 0);
        this.voice(n, t, stepDur * 1.8, 'sawtooth', 0.22, 700);
      }
      // arpegio
      const arp = [0, 7, 12, 15, 12, 7, 19, 15][s % 8];
      if (s % 2 === 1) this.voice(root + 24 + arp, t, stepDur * 0.9, 'square', 0.06, 2600);
      // percusión
      if (s % 4 === 0) this.kick(t);
      if (s % 8 === 4) this.noise(0.18, 0.35, 3000, 900, 'bandpass', this.musicBus, t);
      if (s % 2 === 1) this.noise(0.04, 0.12, 9000, 7000, 'highpass', this.musicBus, t);
      this.nextNote += stepDur; this.step++;
    }
  }

  private voice(midi: number, t: number, dur: number, type: OscillatorType, vol: number, cutoff: number) {
    const ctx = this.ctx; if (!ctx || !this.musicBus) return;
    const o = ctx.createOscillator(); o.type = type;
    o.frequency.value = 440 * Math.pow(2, (midi - 69) / 12);
    const f = ctx.createBiquadFilter(); f.type = 'lowpass'; f.frequency.value = cutoff;
    const g = ctx.createGain();
    g.gain.setValueAtTime(vol, t); g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    o.connect(f); f.connect(g); g.connect(this.musicBus);
    o.start(t); o.stop(t + dur + 0.02);
  }

  private kick(t: number) {
    const ctx = this.ctx; if (!ctx || !this.musicBus) return;
    const o = ctx.createOscillator(); const g = ctx.createGain();
    o.frequency.setValueAtTime(140, t); o.frequency.exponentialRampToValueAtTime(40, t + 0.15);
    g.gain.setValueAtTime(0.6, t); g.gain.exponentialRampToValueAtTime(0.0001, t + 0.2);
    o.connect(g); g.connect(this.musicBus); o.start(t); o.stop(t + 0.22);
  }

  shutdown() {
    this.stopMusic();
    this.stopEngine();
  }
}

export const sound = new Sound();

