export interface SaveData {
  best: number;
  bestDist: number;
  coins: number;
  unlocked: string[];
  car: string;
  diff: string;
}

const KEY = 'nona.neonHighway.v1';

export function loadSave(): SaveData {
  const base: SaveData = { best: 0, bestDist: 0, coins: 0, unlocked: ['vortex'], car: 'vortex', diff: 'normal' };
  try {
    const raw = localStorage.getItem(KEY);
    if (!raw) return base;
    const d = JSON.parse(raw) as Partial<SaveData>;
    return { ...base, ...d, unlocked: Array.isArray(d.unlocked) && d.unlocked.length ? d.unlocked : base.unlocked };
  } catch {
    return base;
  }
}

export function storeSave(s: SaveData) {
  try { localStorage.setItem(KEY, JSON.stringify(s)); } catch { /* sin almacenamiento */ }
}

export function carById(id: string): CarDef {
  return CARS.find(c => c.id === id) ?? CARS[0];
}

export function diffById(id: string): DiffDef {
  return DIFFS.find(d => d.id === id) ?? DIFFS[1];
}

// Motor principal: render, bucle, jugador, colisiones, puntuación y cámara.
import * as THREE from 'three';
import { setupRenderer } from './three-compat';
import { World, ROAD_HALF, LANES } from './world';
import { ModelKit, disposeShared, glowTexture } from './models';
import { Traffic, Entity } from './traffic';
import { Particles, SpeedLines } from './fx';
import { Input } from './input';
import { sound } from './audio';
import { CarDef, DiffDef, CARS, DIFFS, SECTOR_LEN } from './config';

export interface HudState {
  score: number; distance: number; kmh: number; speedN: number; nitro: number; nitroOn: boolean;
  lives: number; maxLives: number; combo: number; comboT: number; coins: number; sector: number;
  shield: number; magnet: number;
}

export interface RunResult {
  score: number; distance: number; coins: number; bestCombo: number; nearMisses: number; sector: number;
}

export interface GameCallbacks {
  onHud(h: HudState): void;
  onEvent(text: string, color: string): void;
  onGameOver(r: RunResult): void;
}

type Mode = 'attract' | 'play' | 'over';

export class Game {
  readonly input = new Input();
  private renderer: THREE.WebGLRenderer;
  private scene = new THREE.Scene();
  private camera = new THREE.PerspectiveCamera(62, 1, 0.1, 2200);
  private clock = new THREE.Clock();
  private world: World;
  private kit = new ModelKit();
  private traffic: Traffic;
  private fx: Particles;
  private lines: SpeedLines;
  private ro: ResizeObserver;
  private raf = 0;
  private player = new THREE.Group();
  private model: THREE.Group | null = null;
  private shieldMesh: THREE.Mesh;
  private beamMat: THREE.MeshBasicMaterial;
  private extraGeo: THREE.BufferGeometry[] = [];
  private mode: Mode = 'attract';
  paused = false;
  private car: CarDef = CARS[0];
  private diff: DiffDef = DIFFS[1];
  private time = 0;
  private hudT = 0;
  private overT = 0;
  private scrapeT = 0;
  private camShake = 0;
  private lookTarget = new THREE.Vector3();
  // estado de la partida
  private speed = 30; private px = 0; private vx = 0;
  private nitro = 0.6; private nitroOn = false; private nitroMin = 0;
  private lives = 3; private invuln = 0; private shield = 0; private magnet = 0;
  private score = 0; private dist = 0; private coins = 0;
  private combo = 0; private comboT = 0; private bestCombo = 0; private nearMisses = 0; private sector = 1;

  constructor(private host: HTMLElement, private cb: GameCallbacks) {
    this.renderer = new THREE.WebGLRenderer({ antialias: true, powerPreference: 'high-performance' });
    setupRenderer(this.renderer);
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
    const cv = this.renderer.domElement;
    cv.style.width = '100%'; cv.style.height = '100%'; cv.style.display = 'block';
    host.appendChild(cv);

    this.world = new World(this.scene);
    this.traffic = new Traffic(this.scene, this.kit);
    this.fx = new Particles(this.scene);
    this.lines = new SpeedLines(this.scene);

    // faros del jugador (conos aditivos) y escudo
    const beamGeo = new THREE.ConeGeometry(1.5, 16, 18, 1, true).translate(0, -8, 0).rotateX(Math.PI / 2);
    this.extraGeo.push(beamGeo);
    this.beamMat = new THREE.MeshBasicMaterial({ color: 0xbfe6ff, transparent: true, opacity: 0.07, blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide });
    for (const s of [-1, 1]) {
      const b = new THREE.Mesh(beamGeo, this.beamMat); b.position.set(s * 0.62, 0.6, -2.2); this.player.add(b);
    }
    const spotGeo = new THREE.PlaneGeometry(1, 1).rotateX(-Math.PI / 2); this.extraGeo.push(spotGeo);
    const spot = new THREE.Mesh(spotGeo, new THREE.MeshBasicMaterial({ map: glowTexture(), color: 0x6a8cff, transparent: true, opacity: 0.22, blending: THREE.AdditiveBlending, depthWrite: false }));
    spot.scale.set(5, 1, 14); spot.position.set(0, 0.03, -11); this.player.add(spot);
    const shGeo = new THREE.IcosahedronGeometry(1, 1); this.extraGeo.push(shGeo);
    this.shieldMesh = new THREE.Mesh(shGeo, new THREE.MeshBasicMaterial({ color: 0x6bff9a, wireframe: true, transparent: true, opacity: 0.55, blending: THREE.AdditiveBlending, depthWrite: false }));
    this.shieldMesh.scale.set(1.7, 1.2, 3); this.shieldMesh.position.y = 0.7; this.shieldMesh.visible = false;
    this.player.add(this.shieldMesh);
    this.scene.add(this.player);
    this.setCar(this.car);

    this.input.attach();
    this.input.enabled = false;
    this.ro = new ResizeObserver(() => this.resize());
    this.ro.observe(host);
    this.resize();
    this.traffic.prefill(this.spawnCtx());
    this.camera.position.set(0, 3.3, 8);
    this.frame();
  }

  private spawnCtx() {
    return { sector: this.sector, density: this.diff.density, trafficSpeed: this.diff.trafficSpeed };
  }

  private resize() {
    const w = Math.max(1, this.host.clientWidth); const h = Math.max(1, this.host.clientHeight);
    this.renderer.setSize(w, h, false);
    this.camera.aspect = w / h;
    this.camera.fov = w < h ? 78 : 62;
    this.camera.updateProjectionMatrix();
  }

  setCar(def: CarDef) {
    this.car = def;
    if (this.model) this.player.remove(this.model);
    this.model = this.kit.car(def.body, def.accent, 'sport', true);
    this.player.add(this.model);
  }

  newRun(car: CarDef, diff: DiffDef) {
    this.setCar(car); this.diff = diff;
    this.mode = 'play'; this.paused = false; this.input.enabled = true;
    this.speed = car.maxSpeed * 0.6; this.px = LANES[1]; this.vx = 0;
    this.nitro = 0.5; this.nitroOn = false; this.lives = diff.lives; this.invuln = 0;
    this.shield = 0; this.magnet = 0; this.score = 0; this.dist = 0; this.coins = 0;
    this.combo = 0; this.comboT = 0; this.bestCombo = 0; this.nearMisses = 0; this.sector = 1; this.overT = 0;
    this.player.visible = true;
    this.fx.clear(); this.traffic.reset(); this.traffic.prefill(this.spawnCtx());
    sound.startEngine(); sound.startMusic();
    this.cb.onEvent('¡A CORRER!', '#22e6ff');
    this.pushHud();
  }

  toAttract() {
    this.mode = 'attract'; this.paused = false; this.input.enabled = false;
    this.player.visible = true; this.shield = 0; this.magnet = 0; this.nitroOn = false;
    this.sector = 1; this.diff = DIFFS[1];
    sound.stopEngine(); sound.stopMusic();
  }

  setPaused(p: boolean) {
    this.paused = p;
    this.input.enabled = !p && this.mode === 'play';
    if (p) sound.engine(0, false);
  }

  private frame = () => {
    this.raf = requestAnimationFrame(this.frame);
    const dt = Math.min(0.05, this.clock.getDelta());
    if (!this.paused) this.step(dt);
    this.renderer.render(this.scene, this.camera);
  };

  private step(dt: number) {
    this.time += dt;
    if (this.mode === 'play') this.control(dt);
    else if (this.mode === 'attract') this.autopilot(dt);
    else this.speed = Math.max(0, this.speed - 28 * dt);

    const dz = this.speed * dt;
    this.world.update(dt, this.speed, this.time);
    this.traffic.update(dt, this.speed, this.time);
    if (this.mode !== 'over') this.traffic.spawnTick(dz, this.spawnCtx());
    if (this.mode === 'play') { this.collide(); this.collect(dt); this.progress(dt, dz); }
    this.animatePlayer(dt);
    this.fx.update(dt, dz);
    this.lines.update(dt, this.speed, this.nitroOn ? 1 : Math.max(0, (this.speed / this.car.maxSpeed - 0.97) * 3), this.px);
    this.updateCamera(dt);

    if (this.mode === 'over') {
      this.overT -= dt;
      if (this.overT <= 0 && this.overT > -100) { this.overT = -1000; this.cb.onGameOver(this.result()); }
    }
    this.hudT -= dt;
    if (this.hudT <= 0 && this.mode === 'play') { this.hudT = 0.1; this.pushHud(); }
  }

  private control(dt: number) {
    const c = this.car; const inp = this.input;
    if (inp.get('nitro') && !this.nitroOn && this.nitro > 0.12) {
      this.nitroOn = true; this.nitroMin = 1.8; sound.nitro(); this.camShake = Math.max(this.camShake, 0.25);
      this.cb.onEvent('NITRO', '#22e6ff');
    }
    if (this.nitroOn) {
      this.nitro -= dt * 0.3 / c.nitroCap; this.nitroMin -= dt;
      if (this.nitro <= 0 || (!inp.get('nitro') && this.nitroMin <= 0)) { this.nitroOn = false; this.nitro = Math.max(0, this.nitro); }
    } else this.nitro = Math.min(1, this.nitro + dt * 0.02);

    const braking = inp.get('down');
    let target = c.maxSpeed * 0.74;
    if (inp.get('up')) target = c.maxSpeed;
    if (braking) target = 14;
    if (this.nitroOn) target = c.maxSpeed * 1.5;
    const rate = braking ? 40 : this.nitroOn ? c.accel * 2.4 : this.speed > target ? 9 : c.accel;
    this.speed += THREE.MathUtils.clamp(target - this.speed, -rate * dt, rate * dt);

    const sN = this.speed / c.maxSpeed;
    const tvx = inp.steer * c.handling * (0.7 + 0.3 * Math.min(1, sN));
    this.vx += (tvx - this.vx) * (1 - Math.exp(-dt * 9));
    this.px += this.vx * dt;
    const lim = ROAD_HALF - 1.15;
    if (Math.abs(this.px) > lim) {
      this.px = Math.sign(this.px) * lim;
      if (Math.sign(inp.steer) === Math.sign(this.px) && inp.steer !== 0) {
        this.speed *= 1 - dt * 0.6; this.scrapeT -= dt;
        if (this.scrapeT <= 0) { this.scrapeT = 0.12; sound.scrape(); }
        for (let i = 0; i < 2; i++) this.fx.emit(this.px + Math.sign(this.px) * 1, 0.4, -1 + Math.random() * 2, -Math.sign(this.px) * 3, 3 + Math.random() * 3, 6, 0xffd27a, 0.4, 1, 12);
      }
      this.vx = 0;
    }
    sound.engine(sN, this.nitroOn);
  }

  private autopilot(dt: number) {
    const target = LANES[this.traffic.bestLane(this.px)];
    this.speed += (this.car.maxSpeed * 0.85 - this.speed) * Math.min(1, dt);
    const tvx = THREE.MathUtils.clamp((target - this.px) * 2.2, -11, 11);
    this.vx += (tvx - this.vx) * (1 - Math.exp(-dt * 6));
    this.px += this.vx * dt;
    // en modo demo los coches que se acercan demasiado se apartan sin choque
    for (const e of this.traffic.cars) if (!e.hit && Math.abs(e.z) < 3 && Math.abs(e.x - this.px) < 2) e.speed = this.speed + 6;
  }

  private collide() {
    const c = this.model!.userData as { w: number; l: number };
    for (const e of this.traffic.cars) {
      if (e.hit) continue;
      const dx = Math.abs(e.x - this.px); const dz = Math.abs(e.z);
      if (this.invuln <= 0 && dx < (e.w + c.w) / 2 * 0.86 && dz < (e.l + c.l) / 2 * 0.9) { this.crash(e); continue; }
      if (e.prevZ < 0 && e.z >= 0 && !e.passed) {
        e.passed = true;
        const gap = dx - (e.w + c.w) / 2;
        if (gap < 1.15) this.nearMiss(e);
        else this.score += 20 * this.diff.scoreMul;
      }
    }
  }

  private nearMiss(e: Entity) {
    this.combo++; this.comboT = 3.2; this.nearMisses++;
    this.bestCombo = Math.max(this.bestCombo, this.combo);
    const pts = Math.round(150 * this.combo * this.diff.scoreMul);
    this.score += pts;
    this.nitro = Math.min(1, this.nitro + 0.08);
    sound.nearMiss(this.combo);
    const side = Math.sign(e.x - this.px) || 1;
    for (let i = 0; i < 14; i++) this.fx.emit(this.px + side * 1.1, 0.7, 0, side * (2 + Math.random() * 4), Math.random() * 4, (Math.random() - 0.5) * 6, 0x5cf2ff, 0.5, 2, 4);
    this.cb.onEvent(this.combo > 1 ? `¡AL LÍMITE! x${this.combo}  +${pts}` : `¡AL LÍMITE!  +${pts}`, this.combo >= 5 ? '#ffc23d' : '#ff3bd9');
  }

  private crash(e: Entity) {
    e.hit = true; e.vy = 7; e.spin = (Math.random() < 0.5 ? -1 : 1) * (3 + Math.random() * 3);
    e.speed = Math.max(e.speed, this.speed * 0.9);
    const x = (e.x + this.px) / 2;
    if (this.shield > 0) {
      this.shield = 0; sound.shieldHit(); this.invuln = 0.8; this.camShake = 0.5;
      this.score += 250 * this.diff.scoreMul;
      this.fx.burst(x, 1, -1.5, 0x6bff9a, 40, 12, 0.8, 4);
      this.cb.onEvent('¡ESCUDO! +250', '#6bff9a');
      return;
    }
    this.lives--; this.invuln = 2; this.speed *= 0.45; this.combo = 0; this.comboT = 0; this.nitroOn = false;
    this.camShake = 1.1; sound.crash();
    this.fx.burst(x, 1, -1.5, 0xffb020, 50, 14, 0.9, 10);
    this.fx.burst(x, 1, -1.5, 0xff2bd6, 30, 10, 0.7, 6);
    if (this.lives <= 0) {
      this.mode = 'over'; this.overT = 1.6; this.input.enabled = false;
      sound.stopEngine(); sound.stopMusic(); sound.gameOver();
      this.fx.burst(this.px, 1, 0, 0xffffff, 60, 16, 1.2, 8);
      this.pushHud();
    } else this.cb.onEvent('¡CHOQUE!', '#ff4d6d');
  }

  private collect(dt: number) {
    const p = this.traffic.pickups;
    for (let i = p.length - 1; i >= 0; i--) {
      const e = p[i];
      if (e.kind === 'coin' && this.magnet > 0 && e.z > -14 && e.z < 2) {
        e.x += (this.px - e.x) * Math.min(1, dt * 10); e.z += (0 - e.z) * Math.min(1, dt * 6);
      }
      if (Math.abs(e.x - this.px) < 1.6 && Math.abs(e.z) < 1.8) {
        const k = e.kind;
        if (k === 'coin') { this.coins++; this.score += 50 * this.diff.scoreMul; sound.coin(); this.fx.burst(e.x, 1, e.z, 0xffc83d, 10, 5, 0.5, 3); }
        else {
          sound.powerUp(); this.fx.burst(e.x, 1, e.z, k === 'nitro' ? 0x2ee8ff : k === 'shield' ? 0x6bff9a : 0xff3bd9, 30, 9, 0.8, 2);
          if (k === 'nitro') { this.nitro = Math.min(1, this.nitro + 0.45); this.cb.onEvent('+NITRO', '#22e6ff'); }
          if (k === 'shield') { this.shield = 12; this.cb.onEvent('ESCUDO ACTIVO', '#6bff9a'); }
          if (k === 'magnet') { this.magnet = 10; this.cb.onEvent('IMÁN DE MONEDAS', '#ff3bd9'); }
        }
        this.traffic.removePickup(i);
      }
    }
  }

  private progress(dt: number, dz: number) {
    this.dist += dz;
    this.score += dz * (1 + this.combo * 0.15) * this.diff.scoreMul;
    this.invuln = Math.max(0, this.invuln - dt);
    this.shield = Math.max(0, this.shield - dt);
    this.magnet = Math.max(0, this.magnet - dt);
    if (this.comboT > 0) { this.comboT -= dt; if (this.comboT <= 0) this.combo = 0; }
    const sec = 1 + Math.floor(this.dist / SECTOR_LEN);
    if (sec !== this.sector) {
      this.sector = sec; sound.sector();
      this.cb.onEvent(`SECTOR ${sec}`, '#ffc23d');
    }
  }

  private animatePlayer(dt: number) {
    const m = this.model!;
    this.player.position.x = this.px;
    m.rotation.y = -this.vx * 0.022;
    m.rotation.z = this.vx * 0.012;
    m.position.y = Math.sin(this.time * 30) * 0.012 * (this.speed / 40);
    m.rotation.x = this.nitroOn ? -0.03 : 0;
    this.player.visible = this.mode === 'over' ? false : !(this.invuln > 0 && this.mode === 'play' && Math.floor(this.time * 14) % 2 === 0);
    this.shieldMesh.visible = this.shield > 0 && (this.shield > 2 || Math.floor(this.time * 8) % 2 === 0);
    this.shieldMesh.rotation.y += dt * 1.5;
    this.beamMat.opacity = 0.06 + (this.nitroOn ? 0.04 : 0);
    if (this.mode === 'over') {
      if (Math.random() < 0.6) this.fx.emit(this.px + (Math.random() - 0.5), 0.8, 0, (Math.random() - 0.5) * 2, 4 + Math.random() * 3, 0, Math.random() < 0.5 ? 0xff5a1f : 0xffc23d, 0.9, 1, -2);
      return;
    }
    // escape: llamas azules con nitro, chispas tenues sin él
    const n = this.nitroOn ? 4 : (Math.random() < 0.3 ? 1 : 0);
    for (let i = 0; i < n; i++) {
      for (const s of [-1, 1]) {
        this.fx.emit(this.px + s * 0.5 + (Math.random() - 0.5) * 0.15, 0.4, 2.3, (Math.random() - 0.5) * 1.5, Math.random() * 0.8, 8 + Math.random() * 6,
          this.nitroOn ? (Math.random() < 0.5 ? 0x4fd8ff : this.car.accent) : 0x8a5cff, this.nitroOn ? 0.35 : 0.25, 3, 0);
      }
    }
  }

  private updateCamera(dt: number) {
    const sN = this.speed / this.car.maxSpeed;
    const k = 1 - Math.exp(-dt * 5);
    const cam = this.camera;
    let tx = this.px * 0.6; let ty = 3.2; let tz = 7.8 + (this.nitroOn ? -0.8 : 0);
    if (this.mode === 'attract') { tx = this.px + Math.sin(this.time * 0.25) * 4.5; ty = 2.4 + Math.sin(this.time * 0.17) * 0.6; tz = 7.5; }
    if (this.mode === 'over') { ty = 5; tz = 11; }
    cam.position.x += (tx - cam.position.x) * k;
    cam.position.y += (ty - cam.position.y) * k;
    cam.position.z += (tz - cam.position.z) * k;
    this.camShake = Math.max(0, this.camShake - dt * 1.8);
    const sh = this.camShake * this.camShake * 0.6 + (this.nitroOn ? 0.03 : 0);
    cam.position.x += (Math.random() - 0.5) * sh; cam.position.y += (Math.random() - 0.5) * sh;
    this.lookTarget.set(this.px * (this.mode === 'attract' ? 1 : 0.8), 1.1, -14);
    cam.lookAt(this.lookTarget);
    const baseFov = this.host.clientWidth < this.host.clientHeight ? 78 : 62;
    const fov = baseFov + Math.min(1.5, sN) * 6 + (this.nitroOn ? 12 : 0);
    if (Math.abs(cam.fov - fov) > 0.05) { cam.fov += (fov - cam.fov) * k; cam.updateProjectionMatrix(); }
  }

  private result(): RunResult {
    return { score: Math.round(this.score), distance: Math.round(this.dist), coins: this.coins, bestCombo: this.bestCombo, nearMisses: this.nearMisses, sector: this.sector };
  }

  private pushHud() {
    this.cb.onHud({
      score: Math.round(this.score), distance: Math.round(this.dist), kmh: Math.round(this.speed * 4.2),
      speedN: this.speed / (this.car.maxSpeed * 1.5), nitro: this.nitro, nitroOn: this.nitroOn,
      lives: Math.max(0, this.lives), maxLives: this.diff.lives, combo: this.combo, comboT: this.comboT / 3.2,
      coins: this.coins, sector: this.sector, shield: this.shield, magnet: this.magnet,
    });
  }

  dispose() {
    cancelAnimationFrame(this.raf);
    this.ro.disconnect();
    this.input.detach();
    sound.stopEngine(); sound.stopMusic();
    this.traffic.dispose(); this.fx.dispose(); this.lines.dispose(); this.world.dispose();
    this.player.traverse(o => { const m = (o as THREE.Mesh).material as THREE.Material | undefined; if (m && o !== this.model) m.dispose(); });
    this.extraGeo.forEach(g => g.dispose());
    this.kit.dispose(); disposeShared();
    this.renderer.dispose();
    this.renderer.domElement.remove();
  }
}

// Efectos: partículas aditivas en pool y líneas de velocidad del nitro.
import * as THREE from 'three';
import { glowTexture } from './models';

const MAX = 420;

export class Particles {
  readonly points: THREE.Points;
  private pos = new Float32Array(MAX * 3);
  private col = new Float32Array(MAX * 3);
  private vel = new Float32Array(MAX * 3);
  private base = new Float32Array(MAX * 3);
  private life = new Float32Array(MAX);
  private maxLife = new Float32Array(MAX);
  private drag = new Float32Array(MAX);
  private grav = new Float32Array(MAX);
  private cursor = 0;
  private geo: THREE.BufferGeometry;
  private mat: THREE.PointsMaterial;
  private tmp = new THREE.Color();

  constructor(scene: THREE.Scene) {
    this.geo = new THREE.BufferGeometry();
    this.geo.setAttribute('position', new THREE.BufferAttribute(this.pos, 3));
    this.geo.setAttribute('color', new THREE.BufferAttribute(this.col, 3));
    this.mat = new THREE.PointsMaterial({
      size: 0.7, map: glowTexture(), vertexColors: true, transparent: true,
      depthWrite: false, blending: THREE.AdditiveBlending, sizeAttenuation: true,
    });
    this.points = new THREE.Points(this.geo, this.mat);
    this.points.frustumCulled = false;
    for (let i = 0; i < MAX; i++) this.pos[i * 3 + 1] = -999;
    scene.add(this.points);
  }

  emit(x: number, y: number, z: number, vx: number, vy: number, vz: number, color: number, life: number, drag = 1.5, grav = 0) {
    const i = this.cursor; this.cursor = (this.cursor + 1) % MAX;
    this.pos[i * 3] = x; this.pos[i * 3 + 1] = y; this.pos[i * 3 + 2] = z;
    this.vel[i * 3] = vx; this.vel[i * 3 + 1] = vy; this.vel[i * 3 + 2] = vz;
    this.tmp.setHex(color);
    this.base[i * 3] = this.tmp.r; this.base[i * 3 + 1] = this.tmp.g; this.base[i * 3 + 2] = this.tmp.b;
    this.life[i] = life; this.maxLife[i] = life; this.drag[i] = drag; this.grav[i] = grav;
  }

  burst(x: number, y: number, z: number, color: number, count: number, speed: number, life = 0.8, grav = 6) {
    for (let k = 0; k < count; k++) {
      const a = Math.random() * Math.PI * 2; const u = Math.random() * 2 - 1;
      const r = Math.sqrt(1 - u * u) * speed * (0.4 + Math.random() * 0.6);
      this.emit(x, y, z, Math.cos(a) * r, Math.abs(u) * speed * 0.8 + 1, Math.sin(a) * r, color, life * (0.6 + Math.random() * 0.6), 1.2, grav);
    }
  }

  /** dz: desplazamiento del mundo este frame (las partículas viven en el mundo). */
  update(dt: number, dz: number) {
    for (let i = 0; i < MAX; i++) {
      if (this.life[i] <= 0) continue;
      this.life[i] -= dt;
      const j = i * 3;
      if (this.life[i] <= 0) { this.pos[j + 1] = -999; this.col[j] = this.col[j + 1] = this.col[j + 2] = 0; continue; }
      const dr = Math.max(0, 1 - this.drag[i] * dt);
      this.vel[j] *= dr; this.vel[j + 1] = this.vel[j + 1] * dr - this.grav[i] * dt; this.vel[j + 2] *= dr;
      this.pos[j] += this.vel[j] * dt;
      this.pos[j + 1] = Math.max(0.05, this.pos[j + 1] + this.vel[j + 1] * dt);
      this.pos[j + 2] += this.vel[j + 2] * dt + dz;
      const f = this.life[i] / this.maxLife[i];
      this.col[j] = this.base[j] * f; this.col[j + 1] = this.base[j + 1] * f; this.col[j + 2] = this.base[j + 2] * f;
    }
    this.geo.attributes.position.needsUpdate = true;
    this.geo.attributes.color.needsUpdate = true;
  }

  clear() {
    for (let i = 0; i < MAX; i++) { this.life[i] = 0; this.pos[i * 3 + 1] = -999; }
  }

  dispose() {
    this.points.parent?.remove(this.points);
    this.geo.dispose(); this.mat.dispose();
  }
}

const LINES = 46;

export class SpeedLines {
  readonly mesh: THREE.InstancedMesh;
  private data: { x: number; y: number; z: number; len: number }[] = [];
  private mat: THREE.MeshBasicMaterial;
  private geo: THREE.BoxGeometry;
  private d = new THREE.Object3D();

  constructor(scene: THREE.Scene) {
    this.geo = new THREE.BoxGeometry(0.05, 0.05, 1);
    this.mat = new THREE.MeshBasicMaterial({ color: 0x9ff6ff, transparent: true, opacity: 0, blending: THREE.AdditiveBlending, depthWrite: false, fog: false });
    this.mesh = new THREE.InstancedMesh(this.geo, this.mat, LINES);
    this.mesh.frustumCulled = false;
    for (let i = 0; i < LINES; i++) this.data.push(this.spawn(-Math.random() * 70));
    scene.add(this.mesh);
  }

  private spawn(z: number) {
    const a = Math.random() * Math.PI * 2; const r = 3 + Math.random() * 9;
    return { x: Math.cos(a) * r * 1.4, y: 2.5 + Math.sin(a) * r * 0.7, z, len: 3 + Math.random() * 6 };
  }

  update(dt: number, speed: number, intensity: number, cx: number) {
    this.mat.opacity = THREE.MathUtils.lerp(this.mat.opacity, intensity * 0.75, Math.min(1, dt * 8));
    this.mesh.visible = this.mat.opacity > 0.02;
    if (!this.mesh.visible) return;
    for (let i = 0; i < LINES; i++) {
      const l = this.data[i];
      l.z += speed * 2.2 * dt;
      if (l.z > 12) this.data[i] = this.spawn(-60 - Math.random() * 20);
      const p = this.data[i];
      this.d.position.set(cx + p.x, Math.max(0.3, p.y), p.z);
      this.d.scale.set(1, 1, p.len * (0.6 + intensity));
      this.d.updateMatrix();
      this.mesh.setMatrixAt(i, this.d.matrix);
    }
    this.mesh.instanceMatrix.needsUpdate = true;
  }

  dispose() {
    this.mesh.parent?.remove(this.mesh);
    this.geo.dispose(); this.mat.dispose();
  }
}

// Entrada unificada: teclado (flechas + WASD) y botones táctiles virtuales.

export interface VirtualPad {
  left: boolean;
  right: boolean;
  up: boolean;
  down: boolean;
  nitro: boolean;
}

const MAP: Record<string, keyof VirtualPad> = {
  ArrowLeft: 'left', KeyA: 'left',
  ArrowRight: 'right', KeyD: 'right',
  ArrowUp: 'up', KeyW: 'up',
  ArrowDown: 'down', KeyS: 'down',
  Space: 'nitro', ShiftLeft: 'nitro', ShiftRight: 'nitro',
};

export class Input {
  private keys: VirtualPad = { left: false, right: false, up: false, down: false, nitro: false };
  virtual: VirtualPad = { left: false, right: false, up: false, down: false, nitro: false };
  enabled = true;

  private onDown = (e: KeyboardEvent) => {
    const k = MAP[e.code];
    if (!k) return;
    if (this.enabled) e.preventDefault();
    this.keys[k] = true;
  };

  private onUp = (e: KeyboardEvent) => {
    const k = MAP[e.code];
    if (k) this.keys[k] = false;
  };

  private onBlur = () => {
    (Object.keys(this.keys) as (keyof VirtualPad)[]).forEach(k => { this.keys[k] = false; });
  };

  attach() {
    window.addEventListener('keydown', this.onDown);
    window.addEventListener('keyup', this.onUp);
    window.addEventListener('blur', this.onBlur);
  }

  detach() {
    window.removeEventListener('keydown', this.onDown);
    window.removeEventListener('keyup', this.onUp);
    window.removeEventListener('blur', this.onBlur);
  }

  get(k: keyof VirtualPad) {
    return this.keys[k] || this.virtual[k];
  }

  /** -1 izquierda, +1 derecha */
  get steer() {
    return (this.get('right') ? 1 : 0) - (this.get('left') ? 1 : 0);
  }
}

// Modelos procedurales: coches, camiones, barreras y power-ups (geometría y materiales compartidos).
import * as THREE from 'three';
import { srgbTexture } from './three-compat';

let glowTex: THREE.CanvasTexture | null = null;
/** Degradado radial blanco para halos y partículas (compartido). */
export function glowTexture() {
  if (glowTex) return glowTex;
  const c = document.createElement('canvas'); c.width = c.height = 64;
  const g = c.getContext('2d')!;
  const grd = g.createRadialGradient(32, 32, 0, 32, 32, 32);
  grd.addColorStop(0, 'rgba(255,255,255,1)');
  grd.addColorStop(0.25, 'rgba(255,255,255,0.55)');
  grd.addColorStop(1, 'rgba(255,255,255,0)');
  g.fillStyle = grd; g.fillRect(0, 0, 64, 64);
  glowTex = srgbTexture(new THREE.CanvasTexture(c)) as THREE.CanvasTexture;
  return glowTex;
}

export function disposeShared() {
  glowTex?.dispose(); glowTex = null;
}

export type TrafficKind = 'sedan' | 'sport' | 'truck' | 'barrier';
export type PickupKind = 'coin' | 'nitro' | 'shield' | 'magnet';

export const TRAFFIC_COLORS = [0x3a2a7a, 0x7a1f5c, 0x1f4d7a, 0x5a5a6e, 0x7a3a1f, 0x1f6e5a, 0xd0d0dc];
export const TRAFFIC_ACCENTS = [0x2ee8ff, 0xff3bd9, 0xffc23d, 0x7cff6b, 0x9b6bff];

export class ModelKit {
  private mats = new Map<string, THREE.Material>();
  private geos = new Map<string, THREE.BufferGeometry>();
  private stripeTex: THREE.CanvasTexture | null = null;

  geo(key: string, make: () => THREE.BufferGeometry) {
    let g = this.geos.get(key);
    if (!g) { g = make(); this.geos.set(key, g); }
    return g;
  }

  private mat<T extends THREE.Material>(key: string, make: () => T): T {
    let m = this.mats.get(key) as T | undefined;
    if (!m) { m = make(); this.mats.set(key, m); }
    return m;
  }

  paint(color: number) {
    return this.mat('paint' + color, () => new THREE.MeshStandardMaterial({ color, metalness: 0.55, roughness: 0.28 }));
  }
  neon(color: number) {
    return this.mat('neon' + color, () => new THREE.MeshBasicMaterial({ color }));
  }
  glass(accent: number) {
    return this.mat('glass' + accent, () => new THREE.MeshStandardMaterial({ color: 0x07060f, metalness: 0.9, roughness: 0.12, emissive: accent, emissiveIntensity: 0.12 }));
  }
  glowSprite(color: number, opacity = 0.9) {
    return this.mat('gs' + color + '_' + opacity, () => new THREE.SpriteMaterial({ map: glowTexture(), color, blending: THREE.AdditiveBlending, transparent: true, depthWrite: false, opacity }));
  }
  glowPlane(color: number) {
    return this.mat('gp' + color, () => new THREE.MeshBasicMaterial({ map: glowTexture(), color, blending: THREE.AdditiveBlending, transparent: true, depthWrite: false, opacity: 0.6 }));
  }

  private box(w: number, h: number, d: number) {
    return this.geo(`b${w.toFixed(2)}_${h.toFixed(2)}_${d.toFixed(2)}`, () => new THREE.BoxGeometry(w, h, d));
  }

  private part(parent: THREE.Object3D, geo: THREE.BufferGeometry, mat: THREE.Material, x: number, y: number, z: number) {
    const m = new THREE.Mesh(geo, mat); m.position.set(x, y, z); parent.add(m); return m;
  }

  private wheels(g: THREE.Group, w: number, zs: number[], r: number) {
    const wg = this.geo('wheel' + r, () => new THREE.CylinderGeometry(r, r, 0.32, 14).rotateZ(Math.PI / 2));
    const rim = this.geo('rim' + r, () => new THREE.TorusGeometry(r * 0.62, 0.05, 6, 16).rotateY(Math.PI / 2));
    const wm = this.paint(0x0a0910);
    for (const z of zs) for (const s of [-1, 1]) {
      this.part(g, wg, wm, s * (w / 2 - 0.05), r, z);
      this.part(g, rim, this.neon(0x4a3a6e), s * (w / 2 + 0.12), r, z);
    }
  }

  /** Perfil lateral extruido a lo ancho (x del perfil = hacia delante). */
  private profile(key: string, pts: [number, number][], width: number) {
    return this.geo(key, () => {
      const sh = new THREE.Shape();
      sh.moveTo(pts[0][0], pts[0][1]);
      for (let i = 1; i < pts.length; i++) sh.lineTo(pts[i][0], pts[i][1]);
      sh.closePath();
      const g = new THREE.ExtrudeGeometry(sh, { depth: width, bevelEnabled: false });
      g.translate(0, 0, -width / 2); g.rotateY(Math.PI / 2);
      return g;
    });
  }

  /** Deportivo/turismo. El frente mira hacia -Z. */
  car(body: number, accent: number, kind: 'sport' | 'sedan' = 'sport', underglow = true) {
    const g = new THREE.Group();
    const sport = kind === 'sport';
    const w = sport ? 1.95 : 1.85; const L = sport ? 4.3 : 4.5;
    const lower: [number, number][] = sport
      ? [[-L / 2, 0.25], [-L / 2, 0.8], [-L * 0.18, 0.84], [L * 0.2, 0.8], [L / 2, 0.48], [L / 2, 0.25]]
      : [[-L / 2, 0.28], [-L / 2, 0.9], [L * 0.28, 0.9], [L / 2, 0.72], [L / 2, 0.28]];
    const cabin: [number, number][] = sport
      ? [[-L * 0.32, 0.82], [-L * 0.1, 1.17], [L * 0.04, 1.18], [L * 0.22, 0.81]]
      : [[-L * 0.38, 0.88], [-L * 0.25, 1.42], [L * 0.1, 1.42], [L * 0.27, 0.88]];
    this.part(g, this.profile('low' + kind, lower, w), this.paint(body), 0, 0, 0);
    this.part(g, this.profile('cab' + kind, cabin, w * 0.84), this.glass(accent), 0, 0, 0);
    const neon = this.neon(accent);
    const tailY = sport ? 0.66 : 0.76;
    for (const s of [-1, 1]) this.part(g, this.box(0.05, 0.06, L * 0.86), neon, s * (w / 2 + 0.01), 0.34, 0);
    this.part(g, this.box(w * 0.9, 0.04, 0.04), neon, 0, sport ? 0.82 : 0.92, L / 2 - 0.02);
    // luces
    this.part(g, this.box(w * 0.92, 0.1, 0.06), this.neon(0xff1a3c), 0, tailY, L / 2 + 0.01);
    const white = this.neon(0xeaf6ff);
    for (const s of [-1, 1]) this.part(g, this.box(0.45, 0.08, 0.06), white, s * w * 0.32, sport ? 0.42 : 0.6, -L / 2 - 0.01);
    for (const s of [-1, 1]) {
      const sp = new THREE.Sprite(this.glowSprite(0xff2040, 0.85));
      sp.position.set(s * w * 0.35, tailY, L / 2 + 0.3); sp.scale.set(1.5, 0.9, 1); g.add(sp);
    }
    if (sport) {
      this.part(g, this.box(w * 0.94, 0.05, 0.34), this.paint(body), 0, 1.0, L / 2 - 0.22);
      for (const s of [-1, 1]) this.part(g, this.box(0.06, 0.2, 0.1), this.paint(0x0a0910), s * w * 0.3, 0.9, L / 2 - 0.22);
      this.part(g, this.box(w * 0.94, 0.03, 0.03), neon, 0, 1.03, L / 2 - 0.05);
    }
    this.wheels(g, w, [-L * 0.31, L * 0.31], 0.36);
    if (underglow) {
      const ug = new THREE.Mesh(this.geo('ug', () => new THREE.PlaneGeometry(1, 1).rotateX(-Math.PI / 2)), this.glowPlane(accent));
      ug.scale.set(w * 1.9, 1, L * 1.25); ug.position.y = 0.04; ug.renderOrder = 2; g.add(ug);
    }
    g.userData = { w, l: L };
    return g;
  }

  truck(body: number, accent: number) {
    const g = new THREE.Group();
    const w = 2.45; const l = 9.4;
    const paint = this.paint(body);
    this.part(g, this.box(w * 0.95, 2.1, 2.3), paint, 0, 1.45, -l / 2 + 1.15);
    this.part(g, this.box(w * 0.9, 0.7, 0.08), this.glass(accent), 0, 1.9, -l / 2 - 0.02);
    const trailer = this.paint(0x1a1428);
    this.part(g, this.box(w, 2.9, l - 2.6), trailer, 0, 2.05, 1.3);
    const neon = this.neon(accent);
    const tl = l - 2.6;
    for (const s of [-1, 1]) for (const y of [0.62, 3.48]) this.part(g, this.box(0.06, 0.07, tl), neon, s * (w / 2 + 0.02), y, 1.3);
    this.part(g, this.box(w, 0.07, 0.06), neon, 0, 3.48, 1.3 + tl / 2 + 0.02);
    this.part(g, this.box(w, 0.07, 0.06), neon, 0, 0.62, 1.3 + tl / 2 + 0.02);
    const red = this.neon(0xff1a3c);
    for (const s of [-1, 1]) {
      this.part(g, this.box(0.4, 0.25, 0.06), red, s * (w / 2 - 0.35), 0.95, 1.3 + tl / 2 + 0.03);
      const sp = new THREE.Sprite(this.glowSprite(0xff2040, 0.85));
      sp.position.set(s * (w / 2 - 0.35), 0.95, 1.3 + tl / 2 + 0.35); sp.scale.set(1.6, 1.1, 1); g.add(sp);
    }
    this.wheels(g, w, [-l / 2 + 1.1, 2.4, 4.0], 0.5);
    g.userData = { w, l };
    return g;
  }

  private stripes() {
    if (this.stripeTex) return this.stripeTex;
    const c = document.createElement('canvas'); c.width = 128; c.height = 32;
    const x = c.getContext('2d')!;
    x.fillStyle = '#111'; x.fillRect(0, 0, 128, 32);
    x.fillStyle = '#ff9a1f';
    for (let i = -2; i < 10; i++) { x.beginPath(); x.moveTo(i * 16, 32); x.lineTo(i * 16 + 8, 32); x.lineTo(i * 16 + 24, 0); x.lineTo(i * 16 + 16, 0); x.fill(); }
    this.stripeTex = srgbTexture(new THREE.CanvasTexture(c)) as THREE.CanvasTexture;
    return this.stripeTex;
  }

  barrier() {
    const g = new THREE.Group();
    const w = 2.9; const l = 0.8;
    const m = this.mat('barrier', () => new THREE.MeshStandardMaterial({ map: this.stripes(), emissiveMap: this.stripes(), emissive: 0xff7a00, emissiveIntensity: 0.55, roughness: 0.5 }));
    this.part(g, this.box(w, 0.7, 0.3), m, 0, 0.95, 0);
    for (const s of [-1, 1]) this.part(g, this.box(0.14, 0.95, 0.5), this.paint(0x2a2238), s * (w / 2 - 0.25), 0.48, 0);
    const amber = this.neon(0xffb020);
    for (const s of [-1, 1]) {
      this.part(g, this.box(0.22, 0.22, 0.22), amber, s * (w / 2 - 0.25), 1.42, 0);
      const sp = new THREE.Sprite(this.glowSprite(0xffa020, 1));
      sp.position.set(s * (w / 2 - 0.25), 1.42, 0.2); sp.scale.set(2.2, 2.2, 1); sp.name = 'flash'; g.add(sp);
    }
    const coneG = this.geo('cone', () => new THREE.ConeGeometry(0.28, 0.75, 10));
    for (const s of [-1, 1]) this.part(g, coneG, this.mat('cone', () => new THREE.MeshStandardMaterial({ color: 0xff6a00, emissive: 0xff3a00, emissiveIntensity: 0.6 })), s * 0.9, 0.38, -1.3);
    g.userData = { w, l };
    return g;
  }

  pickup(kind: PickupKind) {
    const g = new THREE.Group();
    const spin = new THREE.Group(); spin.name = 'spin'; g.add(spin);
    let color = 0xffc83d;
    if (kind === 'coin') {
      const geo = this.geo('coin', () => new THREE.CylinderGeometry(0.55, 0.55, 0.14, 20).rotateX(Math.PI / 2));
      this.part(spin, geo, this.mat('coinM', () => new THREE.MeshStandardMaterial({ color: 0xffd23d, emissive: 0xff9a00, emissiveIntensity: 0.9, metalness: 0.8, roughness: 0.25 })), 0, 0, 0);
      this.part(spin, this.geo('coinR', () => new THREE.TorusGeometry(0.42, 0.05, 6, 20)), this.neon(0xfff2a8), 0, 0, 0.09);
    } else if (kind === 'nitro') {
      color = 0x2ee8ff;
      this.part(spin, this.geo('nitro', () => new THREE.CylinderGeometry(0.34, 0.34, 1.1, 14)), this.mat('nitroM', () => new THREE.MeshStandardMaterial({ color: 0x0a3a66, emissive: 0x18c8ff, emissiveIntensity: 0.9, metalness: 0.7, roughness: 0.3 })), 0, 0, 0);
      this.part(spin, this.geo('nitroC', () => new THREE.CylinderGeometry(0.16, 0.2, 0.3, 10)), this.neon(0xd8fbff), 0, 0.68, 0);
      for (const y of [-0.3, 0.3]) this.part(spin, this.geo('nitroB', () => new THREE.TorusGeometry(0.36, 0.04, 6, 18).rotateX(Math.PI / 2)), this.neon(0x2ee8ff), 0, y, 0);
    } else if (kind === 'shield') {
      color = 0x6bff9a;
      this.part(spin, this.geo('shield', () => new THREE.IcosahedronGeometry(0.62, 0)), this.mat('shieldW', () => new THREE.MeshBasicMaterial({ color: 0x6bff9a, wireframe: true })), 0, 0, 0);
      this.part(spin, this.geo('shieldI', () => new THREE.OctahedronGeometry(0.32, 0)), this.neon(0xc8ffd8), 0, 0, 0);
    } else {
      color = 0xff3bd9;
      this.part(spin, this.geo('magnet', () => new THREE.TorusGeometry(0.42, 0.15, 8, 18, Math.PI)), this.mat('magM', () => new THREE.MeshStandardMaterial({ color: 0xff3bd9, emissive: 0xc0108f, emissiveIntensity: 0.8 })), 0, 0.1, 0);
      for (const s of [-1, 1]) this.part(spin, this.box(0.3, 0.3, 0.3), this.neon(0xf0f0ff), s * 0.42, -0.08, 0);
    }
    const halo = new THREE.Sprite(this.glowSprite(color, 0.7));
    halo.scale.set(kind === 'coin' ? 2.2 : 3, kind === 'coin' ? 2.2 : 3, 1);
    g.add(halo);
    g.userData = { w: 1.3, l: 1.3 };
    return g;
  }

  dispose() {
    this.mats.forEach(m => m.dispose());
    this.geos.forEach(g => g.dispose());
    this.stripeTex?.dispose();
    this.mats.clear(); this.geos.clear();
  }
}

import * as THREE from 'three';

/** Multiplica TODAS las intensidades de luz (r155+ usa unidades físicas). */
export const LIGHT_K = Number(THREE.REVISION) >= 155 ? Math.PI : 1;

export function setupRenderer(r: THREE.WebGLRenderer) {
  const a = r as any; const T = THREE as any;
  if ('outputColorSpace' in a) a.outputColorSpace = T.SRGBColorSpace; else a.outputEncoding = T.sRGBEncoding;
}

export function srgbTexture(t: THREE.Texture) {
  const a = t as any; const T = THREE as any;
  if ('colorSpace' in a) a.colorSpace = T.SRGBColorSpace; else a.encoding = T.sRGBEncoding;
  return t;
}

// Tráfico y objetos de la carretera: generación por oleadas, pooling, IA de cambio de carril.
import * as THREE from 'three';
import { ModelKit, PickupKind, TrafficKind, TRAFFIC_ACCENTS, TRAFFIC_COLORS } from './models';
import { LANES } from './world';

export const SPAWN_Z = -270;
const DESPAWN_FRONT = 26;
const DESPAWN_BACK = -360;

export interface Entity {
  kind: TrafficKind | PickupKind;
  pickup: boolean;
  obj: THREE.Group;
  x: number;
  z: number;
  prevZ: number;
  speed: number;     // velocidad absoluta hacia delante
  w: number;
  l: number;
  lane: number;
  targetLane: number;
  laneTimer: number;
  hit: boolean;
  passed: boolean;
  vy: number;        // salto al ser golpeado
  spin: number;
  poolKey: string;
}

export interface SpawnCtx {
  sector: number;
  density: number;
  trafficSpeed: number;
}

const pick = <T,>(a: T[]) => a[Math.floor(Math.random() * a.length)];

export class Traffic {
  cars: Entity[] = [];
  pickups: Entity[] = [];
  private pools = new Map<string, THREE.Group[]>();
  private nextWave = 30;
  private nextCoins = 40;
  private nextPower = 220;
  private root = new THREE.Group();

  constructor(scene: THREE.Scene, private kit: ModelKit) {
    scene.add(this.root);
  }

  private take(key: string, make: () => THREE.Group) {
    const pool = this.pools.get(key);
    const g = pool && pool.length ? pool.pop()! : make();
    g.visible = true; g.rotation.set(0, 0, 0); g.position.set(0, 0, 0);
    this.root.add(g);
    return g;
  }

  private release(e: Entity) {
    this.root.remove(e.obj);
    let pool = this.pools.get(e.poolKey);
    if (!pool) { pool = []; this.pools.set(e.poolKey, pool); }
    pool.push(e.obj);
  }

  reset() {
    for (const e of this.cars) this.release(e);
    for (const e of this.pickups) this.release(e);
    this.cars = []; this.pickups = [];
    this.nextWave = 20; this.nextCoins = 30; this.nextPower = 180;
  }

  /** Rellena la carretera por delante al empezar. */
  prefill(ctx: SpawnCtx) {
    for (let z = -38; z > SPAWN_Z; z -= 26) this.wave(ctx, z);
    this.coinRow(-18);
  }

  private laneFree(lane: number, z: number, margin = 16) {
    return !this.cars.some(c => Math.abs(c.x - LANES[lane]) < 2 && Math.abs(c.z - z) < margin + c.l / 2);
  }

  spawnCar(kind: TrafficKind, lane: number, z: number, ctx: SpawnCtx) {
    const color = pick(TRAFFIC_COLORS); const accent = pick(TRAFFIC_ACCENTS);
    let key: string; let make: () => THREE.Group; let speed: number;
    if (kind === 'truck') { key = 'truck' + accent; make = () => this.kit.truck(0x2a2a40, accent); speed = 17 + Math.random() * 6; }
    else if (kind === 'barrier') { key = 'barrier'; make = () => this.kit.barrier(); speed = 0; }
    else if (kind === 'sport') { key = 'sport' + color + accent; make = () => this.kit.car(color, accent, 'sport', true); speed = 29 + Math.random() * 8; }
    else { key = 'sedan' + color + accent; make = () => this.kit.car(color, accent, 'sedan', false); speed = 21 + Math.random() * 8; }
    const obj = this.take(key, make);
    const { w, l } = obj.userData as { w: number; l: number };
    const e: Entity = {
      kind, pickup: false, obj, x: LANES[lane], z, prevZ: z, speed: speed * ctx.trafficSpeed, w, l, lane, targetLane: lane,
      laneTimer: 1.5 + Math.random() * 3, hit: false, passed: false, vy: 0, spin: 0, poolKey: key,
    };
    this.cars.push(e);
    return e;
  }

  private wave(ctx: SpawnCtx, z: number) {
    const s = ctx.sector;
    const pTwo = Math.min(0.6, 0.22 + s * 0.06);
    const n = Math.random() < pTwo ? 2 : 1;
    const lanes = [0, 1, 2, 3].sort(() => Math.random() - 0.5).slice(0, n);
    for (const lane of lanes) {
      if (!this.laneFree(lane, z)) continue;
      const r = Math.random();
      let kind: TrafficKind = 'sedan';
      if (s >= 2 && r < 0.12) kind = 'barrier';
      else if (r < 0.34) kind = 'truck';
      else if (r < 0.34 + Math.min(0.3, 0.1 + s * 0.04)) kind = 'sport';
      this.spawnCar(kind, lane, z, ctx);
    }
  }

  private spawnPickup(kind: PickupKind, x: number, z: number) {
    const obj = this.take('p' + kind, () => this.kit.pickup(kind));
    const e: Entity = {
      kind, pickup: true, obj, x, z, prevZ: z, speed: 0, w: 1.3, l: 1.3, lane: 0, targetLane: 0,
      laneTimer: 0, hit: false, passed: false, vy: 0, spin: Math.random() * 6, poolKey: 'p' + kind,
    };
    this.pickups.push(e);
  }

  private coinRow(z: number) {
    let lane = Math.floor(Math.random() * 4);
    const zig = Math.random() < 0.4;
    const n = 5 + Math.floor(Math.random() * 4);
    for (let i = 0; i < n; i++) {
      if (zig && i % 3 === 2) lane = THREE.MathUtils.clamp(lane + (Math.random() < 0.5 ? -1 : 1), 0, 3);
      this.spawnPickup('coin', LANES[lane], z - i * 3.6);
    }
  }

  /** Avanza la generación según la distancia recorrida. */
  spawnTick(dDist: number, ctx: SpawnCtx) {
    this.nextWave -= dDist; this.nextCoins -= dDist; this.nextPower -= dDist;
    if (this.nextWave <= 0) {
      this.wave(ctx, SPAWN_Z);
      const gap = Math.max(15, 34 - ctx.sector * 2.4) / ctx.density;
      this.nextWave = gap * (0.75 + Math.random() * 0.5);
    }
    if (this.nextCoins <= 0) { this.coinRow(SPAWN_Z - 10); this.nextCoins = 70 + Math.random() * 60; }
    if (this.nextPower <= 0) {
      const r = Math.random();
      const kind: PickupKind = r < 0.5 ? 'nitro' : r < 0.75 ? 'shield' : 'magnet';
      this.spawnPickup(kind, pick(LANES), SPAWN_Z - 20);
      this.nextPower = 260 + Math.random() * 200;
    }
  }

  update(dt: number, playerSpeed: number, time: number) {
    // seguir al de delante en el mismo carril para no solaparse
    for (const a of this.cars) {
      if (a.hit || a.speed === 0) continue;
      for (const b of this.cars) {
        if (a === b || b.hit) continue;
        if (Math.abs(a.x - b.x) < 2.2 && b.z < a.z && a.z - b.z < (a.l + b.l) / 2 + 6 && b.speed < a.speed) a.speed = b.speed;
      }
    }
    for (let i = this.cars.length - 1; i >= 0; i--) {
      const e = this.cars[i];
      e.prevZ = e.z;
      e.z += (playerSpeed - e.speed) * dt;
      if (e.hit) {
        e.vy -= 22 * dt; e.obj.position.y = Math.max(0, e.obj.position.y + e.vy * dt);
        e.obj.rotation.y += e.spin * dt; e.obj.rotation.z += e.spin * 0.4 * dt;
        e.speed = Math.max(0, e.speed - 30 * dt);
      } else if (e.kind === 'sport') {
        e.laneTimer -= dt;
        if (e.laneTimer <= 0) {
          e.laneTimer = 2 + Math.random() * 3;
          const cand = e.lane + (Math.random() < 0.5 ? -1 : 1);
          if (cand >= 0 && cand <= 3 && this.laneFree(cand, e.z, 10)) e.targetLane = cand;
        }
        const tx = LANES[e.targetLane];
        const step = 3.2 * dt;
        e.x += THREE.MathUtils.clamp(tx - e.x, -step, step);
        if (Math.abs(tx - e.x) < 0.05) e.lane = e.targetLane;
        e.obj.rotation.y = THREE.MathUtils.clamp((e.x - tx) * 0.08, -0.15, 0.15);
      } else if (e.kind === 'barrier') {
        const on = Math.sin(time * 12) > 0;
        e.obj.children.forEach(c => { if (c.name === 'flash') c.visible = on; });
      }
      e.obj.position.x = e.x; e.obj.position.z = e.z;
      if (e.z > DESPAWN_FRONT || e.z < DESPAWN_BACK) { this.release(e); this.cars.splice(i, 1); }
    }
    for (let i = this.pickups.length - 1; i >= 0; i--) {
      const p = this.pickups[i];
      p.prevZ = p.z;
      p.z += playerSpeed * dt;
      p.spin += dt * 3;
      const sp = p.obj.getObjectByName('spin');
      if (sp) sp.rotation.y = p.spin;
      p.obj.position.set(p.x, 1.05 + Math.sin(p.spin * 1.3) * 0.15, p.z);
      if (p.z > DESPAWN_FRONT) this.removePickup(i);
    }
  }

  removePickup(i: number) {
    this.release(this.pickups[i]);
    this.pickups.splice(i, 1);
  }

  /** Carril más despejado por delante (para el piloto automático del menú). */
  bestLane(px: number) {
    let best = 0; let bestScore = -Infinity;
    for (let l = 0; l < 4; l++) {
      let near = 400;
      for (const c of this.cars) if (Math.abs(c.x - LANES[l]) < 2.4 && c.z < 6 && -c.z < near) near = -c.z;
      const s = near - Math.abs(LANES[l] - px) * 2;
      if (s > bestScore) { bestScore = s; best = l; }
    }
    return best;
  }

  dispose() {
    this.root.parent?.remove(this.root);
    this.cars = []; this.pickups = []; this.pools.clear();
  }
}

// Escenario synthwave: cielo, sol retro, montañas de alambre, ciudad de neón, carretera y farolas.
import * as THREE from 'three';
import { LIGHT_K, srgbTexture } from './three-compat';
import { glowTexture } from './models';

export const LANE_W = 3.4;
export const LANES = [-1.5, -0.5, 0.5, 1.5].map(i => i * LANE_W);
export const ROAD_HALF = LANE_W * 2;
export const FOG_COLOR = 0x240843;
export const FOG_NEAR = 40;
export const FOG_FAR = 330;
const SPAN = 560;      // longitud del tramo que se recicla
const Z_FRONT = 40;    // detrás de la cámara

function roadTextures() {
  const W = 256, H = 512;
  const mk = () => { const c = document.createElement('canvas'); c.width = W; c.height = H; return c; };
  const base = mk(); const glow = mk();
  const b = base.getContext('2d')!; const g = glow.getContext('2d')!;
  b.fillStyle = '#0d0a18'; b.fillRect(0, 0, W, H);
  for (let i = 0; i < 2600; i++) {
    const v = 14 + Math.random() * 22;
    b.fillStyle = `rgb(${v},${v - 4},${v + 12})`;
    b.fillRect(Math.random() * W, Math.random() * H, 2, 2);
  }
  g.fillStyle = '#000'; g.fillRect(0, 0, W, H);
  const lane = W / 4;
  const draw = (ctx: CanvasRenderingContext2D, edge: string, dash: string) => {
    ctx.fillStyle = edge;
    ctx.fillRect(3, 0, 7, H); ctx.fillRect(W - 10, 0, 7, H);
    ctx.fillStyle = dash;
    for (let l = 1; l < 4; l++) {
      if (l === 2) { ctx.fillRect(l * lane - 3, 0, 6, H * 0.5); continue; }
      ctx.fillRect(l * lane - 3, 0, 6, H * 0.45);
    }
  };
  draw(b, '#ff4fd8', '#bdf6ff');
  draw(g, '#ff2bd6', '#33e8ff');
  const tb = srgbTexture(new THREE.CanvasTexture(base));
  const tg = srgbTexture(new THREE.CanvasTexture(glow));
  for (const t of [tb, tg]) {
    t.wrapS = THREE.ClampToEdgeWrapping; t.wrapT = THREE.RepeatWrapping;
    t.repeat.set(1, SPAN / 20); t.anisotropy = 4;
  }
  return { tb, tg };
}

const BUILDING_VS = `
varying vec3 vP; varying vec3 vS; varying vec3 vN; varying float vDepth;
void main(){
  mat4 im = mat4(1.0);
  #ifdef USE_INSTANCING
  im = instanceMatrix;
  #endif
  vS = vec3(length(im[0].xyz), length(im[1].xyz), length(im[2].xyz));
  vP = (position + 0.5) * vS;
  vN = normal;
  vec4 mv = modelViewMatrix * im * vec4(position, 1.0);
  vDepth = -mv.z;
  gl_Position = projectionMatrix * mv;
}`;

const BUILDING_FS = `
uniform vec3 uFog; uniform float uNear; uniform float uFar;
varying vec3 vP; varying vec3 vS; varying vec3 vN; varying float vDepth;
float h(vec2 p){ return fract(sin(dot(p, vec2(12.9898,78.233))) * 43758.5453); }
void main(){
  float side = step(abs(vN.y), 0.5);
  float seed = h(vS.xz + vS.y);
  float u = abs(vN.x) > 0.5 ? vP.z : vP.x;
  float wid = abs(vN.x) > 0.5 ? vS.z : vS.x;
  vec2 cell = vec2(u / 2.0, vP.y / 2.8);
  vec2 id = floor(cell); vec2 f = fract(cell);
  float win = step(0.22, f.x) * step(f.x, 0.78) * step(0.3, f.y) * step(f.y, 0.78);
  float lit = step(0.56, h(id + seed * 31.0 + vN.xz * 7.0));
  vec3 pal = seed < 0.33 ? vec3(0.1, 0.9, 1.0) : (seed < 0.66 ? vec3(1.0, 0.18, 0.85) : vec3(1.0, 0.72, 0.25));
  vec3 wc = mix(vec3(1.0, 0.86, 0.65), pal, 0.55) * (0.45 + 0.75 * h(id + 3.0));
  vec3 col = vec3(0.03, 0.015, 0.06) + win * lit * wc * side;
  float top = smoothstep(vS.y - 0.7, vS.y - 0.15, vP.y) * side;
  col += pal * top * 1.5;
  float e = min(u, wid - u);
  col += pal * (1.0 - smoothstep(0.05, 0.3, e)) * 0.7 * side;
  float fog = smoothstep(uNear, uFar, vDepth);
  gl_FragColor = vec4(mix(col, uFog, fog), 1.0);
}`;

export class World {
  readonly group = new THREE.Group();
  private disposables: { dispose(): void }[] = [];
  private roadTex: THREE.Texture[] = [];
  private gridMat: THREE.ShaderMaterial;
  private sunMat: THREE.ShaderMaterial;
  private poles: THREE.InstancedMesh;
  private lamps: THREE.InstancedMesh;
  private poleZ: number[] = [];
  private halos: THREE.Points;
  private buildings: THREE.InstancedMesh;
  private bData: { x: number; z: number; w: number; h: number; d: number }[] = [];
  private dummy = new THREE.Object3D();

  constructor(scene: THREE.Scene) {
    scene.add(this.group);
    scene.fog = new THREE.Fog(FOG_COLOR, FOG_NEAR, FOG_FAR);
    scene.background = new THREE.Color(0x07020f);
    const add = <T extends THREE.Object3D>(o: T) => { this.group.add(o); return o; };
    const track = <T extends { dispose(): void }>(d: T) => { this.disposables.push(d); return d; };

    // Luces
    add(new THREE.HemisphereLight(0x8a5cff, 0x2a0838, 0.6 * LIGHT_K));
    const sunLight = add(new THREE.DirectionalLight(0xff5ccf, 1.1 * LIGHT_K));
    sunLight.position.set(0, 40, -120);
    const fill = add(new THREE.DirectionalLight(0x4fd8ff, 0.7 * LIGHT_K));
    fill.position.set(-20, 30, 60);

    // Cielo
    const skyGeo = track(new THREE.SphereGeometry(1000, 32, 16));
    const skyMat = track(new THREE.ShaderMaterial({
      side: THREE.BackSide, depthWrite: false,
      vertexShader: `varying vec3 vD; void main(){ vD = normalize(position); gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0); }`,
      fragmentShader: `varying vec3 vD; void main(){
        float y = vD.y;
        vec3 top = vec3(0.02, 0.008, 0.07); vec3 mid = vec3(0.2, 0.04, 0.38); vec3 hor = vec3(1.0, 0.27, 0.55);
        vec3 c = mix(mid, top, smoothstep(0.05, 0.55, y));
        c = mix(hor, c, smoothstep(-0.02, 0.13, y));
        c = mix(c, vec3(0.14, 0.03, 0.26), smoothstep(0.0, -0.1, y));
        gl_FragColor = vec4(c, 1.0); }`,
    }));
    add(new THREE.Mesh(skyGeo, skyMat)).renderOrder = -10;

    // Estrellas
    const starPos: number[] = [];
    for (let i = 0; i < 700; i++) {
      const th = Math.random() * Math.PI * 2; const ph = 0.08 + Math.random() * 1.3;
      starPos.push(Math.cos(th) * Math.cos(ph) * 900, Math.sin(ph) * 900, Math.sin(th) * Math.cos(ph) * 900);
    }
    const starGeo = track(new THREE.BufferGeometry());
    starGeo.setAttribute('position', new THREE.Float32BufferAttribute(starPos, 3));
    const starMat = track(new THREE.PointsMaterial({ color: 0xffe6ff, size: 2, sizeAttenuation: false, fog: false, transparent: true, opacity: 0.85 }));
    add(new THREE.Points(starGeo, starMat));

    // Sol retro con franjas
    this.sunMat = track(new THREE.ShaderMaterial({
      transparent: true, depthWrite: false,
      uniforms: { uTime: { value: 0 } },
      vertexShader: `varying vec2 vUv; void main(){ vUv = uv; gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0); }`,
      fragmentShader: `uniform float uTime; varying vec2 vUv; void main(){
        vec2 p = vUv * 2.0 - 1.0; float r = length(p);
        if (r > 1.0) discard;
        vec3 c = mix(vec3(1.0, 0.12, 0.55), vec3(1.0, 0.86, 0.25), smoothstep(-0.7, 0.75, p.y));
        if (p.y < 0.4) {
          float k = (0.4 - p.y) / 1.4;
          float band = fract(p.y * 9.0 + uTime * 0.35);
          if (band < k * 0.75) discard;
        }
        float edge = smoothstep(1.0, 0.96, r);
        gl_FragColor = vec4(c * 1.15, edge); }`,
    }));
    const sunGeo = track(new THREE.PlaneGeometry(260, 260));
    const sun = add(new THREE.Mesh(sunGeo, this.sunMat));
    sun.position.set(0, 62, -720); sun.renderOrder = -8;
    const haloMat = track(new THREE.SpriteMaterial({ map: glowTexture(), color: 0xff3d9a, blending: THREE.AdditiveBlending, transparent: true, depthWrite: false, fog: false, opacity: 0.75 }));
    const halo = add(new THREE.Sprite(haloMat));
    halo.position.set(0, 45, -730); halo.scale.set(620, 420, 1); halo.renderOrder = -9;

    // Suelo con rejilla neón
    this.gridMat = track(new THREE.ShaderMaterial({
      uniforms: { uOff: { value: 0 }, uFog: { value: new THREE.Color(FOG_COLOR) } },
      vertexShader: `varying vec3 vW; varying float vDepth; void main(){
        vec4 w = modelMatrix * vec4(position, 1.0); vW = w.xyz;
        vec4 mv = viewMatrix * w; vDepth = -mv.z; gl_Position = projectionMatrix * mv; }`,
      fragmentShader: `uniform float uOff; uniform vec3 uFog; varying vec3 vW; varying float vDepth; void main(){
        vec2 g = vec2(vW.x, vW.z - uOff) / 7.0;
        vec2 d = abs(fract(g - 0.5) - 0.5);
        float w = 0.025 + vDepth * 0.0009;
        float line = max(1.0 - smoothstep(w, w * 2.2, d.x), 1.0 - smoothstep(w, w * 2.2, d.y));
        vec3 c = mix(vec3(0.03, 0.0, 0.07), vec3(1.0, 0.16, 0.84), line);
        float fog = smoothstep(30.0, 420.0, vDepth);
        gl_FragColor = vec4(mix(c, uFog * 1.3, fog), 1.0); }`,
    }));
    const ground = add(new THREE.Mesh(track(new THREE.PlaneGeometry(600, 640)), this.gridMat));
    ground.rotation.x = -Math.PI / 2; ground.position.set(0, -0.05, -280);

    // Montañas de alambre
    const mGeo = track(new THREE.PlaneGeometry(240, 520, 40, 52));
    mGeo.rotateX(-Math.PI / 2);
    const pos = mGeo.attributes.position as THREE.BufferAttribute;
    for (let i = 0; i < pos.count; i++) {
      const lx = pos.getX(i); const lz = pos.getZ(i);
      const t = (lx + 120) / 240;
      const ridge = Math.abs(Math.sin(lx * 0.045 + lz * 0.031) + Math.sin(lz * 0.071) * 0.7 + Math.sin(lx * 0.13 - lz * 0.05) * 0.35);
      pos.setY(i, THREE.MathUtils.smoothstep(t, 0.04, 0.35) * (6 + ridge * 34));
    }
    mGeo.computeVertexNormals();
    const mSolid = track(new THREE.MeshBasicMaterial({ color: 0x14032c, polygonOffset: true, polygonOffsetFactor: 1, polygonOffsetUnits: 1, side: THREE.DoubleSide }));
    const mWire = track(new THREE.MeshBasicMaterial({ color: 0xff2bd6, wireframe: true, transparent: true, opacity: 0.5, side: THREE.DoubleSide }));
    for (const s of [-1, 1]) {
      for (const m of [mSolid, mWire]) {
        const mesh = add(new THREE.Mesh(mGeo, m));
        mesh.position.set(s * 165, 0, -360);
        mesh.scale.x = s;
      }
    }

    // Carretera
    const { tb, tg } = roadTextures();
    this.roadTex = [tb, tg]; track(tb); track(tg);
    const roadMat = track(new THREE.MeshStandardMaterial({ map: tb, emissiveMap: tg, emissive: 0xffffff, emissiveIntensity: 1.2, roughness: 0.5, metalness: 0.25 }));
    const road = add(new THREE.Mesh(track(new THREE.PlaneGeometry(ROAD_HALF * 2 + 0.8, SPAN)), roadMat));
    road.rotation.x = -Math.PI / 2; road.position.set(0, 0, Z_FRONT - SPAN / 2);

    // Muros laterales con tira de neón
    const wallGeo = track(new THREE.BoxGeometry(0.5, 0.8, SPAN));
    const wallMat = track(new THREE.MeshStandardMaterial({ color: 0x1a1030, roughness: 0.6, metalness: 0.3 }));
    const stripGeo = track(new THREE.BoxGeometry(0.16, 0.12, SPAN));
    for (const s of [-1, 1]) {
      const wall = add(new THREE.Mesh(wallGeo, wallMat));
      wall.position.set(s * (ROAD_HALF + 0.75), 0.4, Z_FRONT - SPAN / 2);
      const sm = track(new THREE.MeshBasicMaterial({ color: s < 0 ? 0x2ee8ff : 0xff3bd9 }));
      const strip = add(new THREE.Mesh(stripGeo, sm));
      strip.position.set(s * (ROAD_HALF + 0.75), 0.86, Z_FRONT - SPAN / 2);
    }

    // Farolas (instanciadas)
    const POLE_N = 36;
    this.poles = add(new THREE.InstancedMesh(track(new THREE.BoxGeometry(0.28, 7.4, 0.28)), track(new THREE.MeshStandardMaterial({ color: 0x241a3a, metalness: 0.6, roughness: 0.4 })), POLE_N * 2));
    this.lamps = add(new THREE.InstancedMesh(track(new THREE.BoxGeometry(2.4, 0.16, 0.5)), track(new THREE.MeshBasicMaterial({ color: 0xffd6f6 })), POLE_N));
    const haloPos = new Float32Array(POLE_N * 3);
    const hGeo = track(new THREE.BufferGeometry());
    hGeo.setAttribute('position', new THREE.BufferAttribute(haloPos, 3));
    const hMat = track(new THREE.PointsMaterial({ map: glowTexture(), color: 0xff7ae0, size: 7, transparent: true, depthWrite: false, blending: THREE.AdditiveBlending, opacity: 0.8 }));
    this.halos = add(new THREE.Points(hGeo, hMat));
    this.halos.frustumCulled = false;
    for (let i = 0; i < POLE_N; i++) this.poleZ.push(Z_FRONT - (i / POLE_N) * SPAN);

    // Ciudad cercana (edificios con ventanas procedurales)
    const bMat = track(new THREE.ShaderMaterial({
      uniforms: { uFog: { value: new THREE.Color(FOG_COLOR) }, uNear: { value: FOG_NEAR }, uFar: { value: FOG_FAR + 80 } },
      vertexShader: BUILDING_VS, fragmentShader: BUILDING_FS,
    }));
    const B_N = 64;
    this.buildings = add(new THREE.InstancedMesh(track(new THREE.BoxGeometry(1, 1, 1)), bMat, B_N));
    this.buildings.frustumCulled = false;
    for (let i = 0; i < B_N; i++) {
      const s = i % 2 === 0 ? -1 : 1;
      const far = Math.random() < 0.5;
      this.bData.push({
        x: s * ((far ? 52 : 26) + Math.random() * (far ? 40 : 18)),
        z: Z_FRONT - Math.random() * SPAN,
        w: 6 + Math.random() * 9, d: 6 + Math.random() * 10,
        h: far ? 30 + Math.random() * 60 : 10 + Math.random() * 34,
      });
    }

    // Skyline lejano frente al sol
    const skyMatB = bMat.clone(); track(skyMatB);
    skyMatB.uniforms.uNear.value = 300; skyMatB.uniforms.uFar.value = 1400;
    skyMatB.uniforms.uFog.value = new THREE.Color(0x3a0a5a);
    const SK_N = 46;
    const skyline = add(new THREE.InstancedMesh(track(new THREE.BoxGeometry(1, 1, 1)), skyMatB, SK_N));
    for (let i = 0; i < SK_N; i++) {
      const x = (i / SK_N - 0.5) * 900 + (Math.random() - 0.5) * 12;
      const hgt = 20 + Math.random() * 70 * (1 - Math.abs(x) / 600);
      this.dummy.position.set(x, hgt / 2 - 2, -600 - Math.random() * 30);
      this.dummy.scale.set(10 + Math.random() * 16, hgt, 12);
      this.dummy.updateMatrix();
      skyline.setMatrixAt(i, this.dummy.matrix);
    }
    skyline.instanceMatrix.needsUpdate = true;
    skyline.renderOrder = -5;

    this.update(0, 0, 0);
  }

  update(dt: number, speed: number, time: number) {
    const dz = speed * dt;
    for (const t of this.roadTex) t.offset.y += dz / 20;
    this.gridMat.uniforms.uOff.value += dz;
    this.sunMat.uniforms.uTime.value = time;

    const d = this.dummy;
    const hp = (this.halos.geometry.attributes.position as THREE.BufferAttribute);
    for (let i = 0; i < this.poleZ.length; i++) {
      let z = this.poleZ[i] + dz;
      if (z > Z_FRONT) z -= SPAN;
      this.poleZ[i] = z;
      const s = i % 2 === 0 ? -1 : 1;
      d.rotation.set(0, 0, 0); d.scale.set(1, 1, 1);
      d.position.set(s * (ROAD_HALF + 1.5), 3.7, z); d.updateMatrix();
      this.poles.setMatrixAt(i * 2, d.matrix);
      d.position.set(s * (ROAD_HALF + 0.7), 7.3, z); d.scale.set(1.6, 0.12, 0.6); d.updateMatrix();
      this.poles.setMatrixAt(i * 2 + 1, d.matrix);
      d.scale.set(1, 1, 1); d.position.set(s * (ROAD_HALF - 0.3), 7.15, z); d.updateMatrix();
      this.lamps.setMatrixAt(i, d.matrix);
      hp.setXYZ(i, s * (ROAD_HALF - 0.3), 6.9, z);
    }
    this.poles.instanceMatrix.needsUpdate = true;
    this.lamps.instanceMatrix.needsUpdate = true;
    hp.needsUpdate = true;

    for (let i = 0; i < this.bData.length; i++) {
      const b = this.bData[i];
      b.z += dz;
      if (b.z - b.d / 2 > Z_FRONT) b.z -= SPAN;
      d.position.set(b.x, b.h / 2, b.z); d.scale.set(b.w, b.h, b.d); d.updateMatrix();
      this.buildings.setMatrixAt(i, d.matrix);
    }
    this.buildings.instanceMatrix.needsUpdate = true;
  }

  dispose() {
    this.group.parent?.remove(this.group);
    for (const d of this.disposables) d.dispose();
  }
}

.nh-root {
  font-family: 'Segoe UI', 'Trebuchet MS', 'Helvetica Neue', Arial, sans-serif;
  -webkit-user-select: none;
  user-select: none;
  touch-action: none;
}

.nh-title {
  font-style: italic;
  font-weight: 900;
  letter-spacing: 0.04em;
  background: linear-gradient(180deg, #fff6c2 0%, #ffc23d 38%, #ff3bd9 62%, #7a3bff 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  filter: drop-shadow(0 0 18px rgba(255, 59, 217, 0.55)) drop-shadow(0 4px 0 rgba(20, 0, 40, 0.9));
}

.nh-chrome {
  font-style: italic;
  font-weight: 800;
  color: #bff7ff;
  text-shadow: 0 0 10px rgba(34, 230, 255, 0.9), 0 0 24px rgba(34, 230, 255, 0.5);
}

.nh-glass {
  background: linear-gradient(160deg, rgba(30, 8, 60, 0.78), rgba(8, 2, 22, 0.82));
  border: 1px solid rgba(255, 59, 217, 0.35);
  box-shadow: 0 0 24px rgba(255, 59, 217, 0.18), inset 0 0 22px rgba(34, 230, 255, 0.06);
  backdrop-filter: blur(6px);
}

.nh-btn {
  background: linear-gradient(90deg, #ff3bd9, #ff7a3b 55%, #ffc23d);
  color: #1a0228;
  font-weight: 900;
  font-style: italic;
  letter-spacing: 0.12em;
  box-shadow: 0 0 22px rgba(255, 59, 217, 0.6), 0 0 50px rgba(255, 122, 59, 0.3);
  transition: transform 0.12s ease, box-shadow 0.2s ease;
}
.nh-btn:hover { transform: translateY(-2px) scale(1.02); box-shadow: 0 0 30px rgba(255, 59, 217, 0.85), 0 0 70px rgba(255, 194, 61, 0.4); }
.nh-btn:active { transform: scale(0.98); }

.nh-scan {
  pointer-events: none;
  background: repeating-linear-gradient(0deg, rgba(0, 0, 0, 0.12) 0 1px, transparent 1px 3px);
  mix-blend-mode: multiply;
}

.nh-vignette {
  pointer-events: none;
  background: radial-gradient(ellipse at center, transparent 55%, rgba(8, 0, 20, 0.65) 100%);
}

@keyframes nh-pop {
  0% { opacity: 0; transform: translate(-50%, 10px) scale(0.6); }
  18% { opacity: 1; transform: translate(-50%, 0) scale(1.12); }
  30% { transform: translate(-50%, 0) scale(1); }
  80% { opacity: 1; }
  100% { opacity: 0; transform: translate(-50%, -28px) scale(1); }
}
.nh-toast { animation: nh-pop 1.3s ease-out forwards; }

@keyframes nh-pulse { 0%, 100% { opacity: 0.55; } 50% { opacity: 1; } }
.nh-pulse { animation: nh-pulse 1.4s ease-in-out infinite; }

@keyframes nh-hit { 0% { opacity: 0.55; } 100% { opacity: 0; } }
.nh-hit { animation: nh-hit 0.5s ease-out forwards; }
